## 2. TypeScript Interfaces (src/lib/types.ts)

These are the exact data shapes the in-memory storage will hold:

```typescript
// Owner profile, populated during onboarding
interface OwnerProfile {
  name: string;
  default_language: string;           // "hindi" | "english" | etc.
  delivery_instructions: string;      // Generic instructions for ANY delivery partner
  call_preferences: Record<string, string>; // e.g. { "insurance": "decline", "loans": "decline", "recruiters": "log" }
  custom_rules: string[];             // Free-form rules from onboarding
  onboarding_complete: boolean;
}

// Contact added during onboarding phase 2
interface Contact {
  id: number;
  name: string;
  relationship: string;
  phone_number: string;
  priority: "high" | "medium" | "low";
}

// Single conversation turn
interface ConversationTurn {
  role: "caller" | "ai";
  text: string;
  audio_transcript?: string;         // Raw transcript if different from text
  timestamp: number;                  // Unix ms
}

// Call log entry (matches CLAUDE.md data model exactly)
interface CallLog {
  call_id: number;                    // Auto-increment
  phone_number: string;
  caller_name: string | null;
  message: string;                    // Summary of what caller wanted
  conversation_history: ConversationTurn[];
  type: string;                       // DYNAMIC STRING -- not enum
  priority: "high" | "medium" | "low";
  language_states: string[];          // ["hindi", "english", "hindi"]
  timestamp: number;                  // Unix ms
  action_taken: string;               // "bypassed" | "took_message" | "blocked" | "declined" | "escalated"
  session_window_id: string;          // Links to SessionWindow
  owner_verified_type: string | null; // Owner correction from dashboard
}

// Session window for conversation continuity (1-2 hour TTL)
interface SessionWindow {
  id: string;                         // UUID
  phone_number: string;
  conversation_history: ConversationTurn[];
  caller_type: string;
  caller_name: string | null;
  created_at: number;
  expires_at: number;                 // created_at + 2 hours
  current_prompt_key: string;         // Which prompt is active
}

// WebSocket message types for browser <-> server
interface WSClientMessage {
  type: "start_call" | "audio_data" | "end_call" | "start_onboarding" | "onboarding_contacts" | "onboarding_confirm";
  phone_number?: string;
  audio?: string;                     // Base64 PCM16
  contacts?: Contact[];               // For phase 2
  phase?: number;
}

interface WSServerMessage {
  type: "audio_data" | "transcript" | "call_status" | "error" | "caller_info_update" | "onboarding_phase_complete" | "onboarding_summary";
  audio?: string;                     // Base64 PCM16
  transcript?: string;
  status?: string;
  caller_type?: string;
  caller_name?: string;
  priority?: string;
  phase?: number;
  summary?: OwnerProfile;
  error?: string;
}

// Dashboard WebSocket message
interface DashboardEvent {
  type: "new_call" | "call_updated" | "full_sync";
  call?: CallLog;
  calls?: CallLog[];
}
```

