## 3. In-Memory Storage (src/lib/storage.ts)

A singleton module exporting a `storage` object. All server-side code imports from here.

```typescript
class InMemoryStorage {
  owner: OwnerProfile | null = null;
  contacts: Contact[] = [];
  callLogs: CallLog[] = [];
  sessionWindows: Map<string, SessionWindow> = new Map(); // keyed by phone_number
  scammerNumbers: Set<string> = new Set();                 // permanent flags
  private nextCallId = 1;
  private nextContactId = 1;

  // Methods:
  getNextCallId(): number
  getNextContactId(): number
  addContact(c: Omit<Contact, 'id'>): Contact
  removeContact(id: number): void
  findContactByPhone(phone: string): Contact | undefined
  addCallLog(log: Omit<CallLog, 'call_id'>): CallLog
  updateCallLog(call_id: number, updates: Partial<CallLog>): void
  getCallLogs(): CallLog[]   // Returns sorted by priority then timestamp
  getOrCreateSessionWindow(phone: string): SessionWindow
  isSessionWindowActive(phone: string): boolean
  flagScammer(phone: string): void
  isScammer(phone: string): boolean
  cleanExpiredSessions(): void  // Called periodically
}

export const storage = new InMemoryStorage();
```

Key detail: `cleanExpiredSessions()` should be called on a 5-minute interval via `setInterval` in `server.ts`. Session windows older than 2 hours get removed (except scammer flags which persist forever).

