"use client";

import { useVoiceSession } from "@/hooks/useVoiceSession";
import { useCallback } from "react";

interface Props {
  onComplete: (data: Record<string, unknown>) => void;
}

export default function PhasePreferences({ onComplete }: Props) {
  const handlePhaseComplete = useCallback(
    (phase: number, data?: Record<string, unknown>) => {
      if (phase === 3 && data) {
        onComplete(data);
      }
    },
    [onComplete]
  );

  const { status, error, transcript, startSession, endSession } =
    useVoiceSession({
      mode: "onboarding",
      onboardingPhase: 3,
      onPhaseComplete: handlePhaseComplete,
    });

  const isActive = status === "connected";

  return (
    <div className="text-center">
      <h2 className="text-xl font-bold mb-2">Set Your Preferences</h2>
      <p className="text-gray-500 mb-6">
        Tell the AI about delivery instructions, which call types to
        accept/decline, and any custom rules.
      </p>

      {status === "idle" && (
        <button
          onClick={startSession}
          className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-8 rounded-lg text-lg transition-colors"
        >
          Start Voice Setup
        </button>
      )}

      {status === "connecting" && (
        <div className="text-yellow-600 font-medium">Connecting...</div>
      )}

      {isActive && (
        <div className="space-y-4">
          <div className="flex justify-center">
            <div className="w-16 h-16 bg-blue-500 rounded-full animate-pulse flex items-center justify-center">
              <svg className="w-8 h-8 text-white" fill="currentColor" viewBox="0 0 24 24">
                <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zm5-3c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z" />
              </svg>
            </div>
          </div>
          <p className="text-green-600 font-medium">AI is listening — describe your preferences</p>
          <button onClick={endSession} className="text-sm text-gray-500 underline">
            Stop
          </button>
        </div>
      )}

      {error && <p className="text-red-600 mt-4">{error}</p>}

      {transcript.length > 0 && (
        <div className="mt-6 text-left max-w-md mx-auto space-y-2">
          {transcript.map((entry, i) => (
            <div
              key={i}
              className={`text-sm p-2 rounded ${
                entry.role === "ai"
                  ? "bg-gray-100 dark:bg-gray-800"
                  : "bg-blue-50 dark:bg-blue-900/20"
              }`}
            >
              <span className="font-medium text-xs text-gray-500">
                {entry.role === "ai" ? "AI" : "You"}:
              </span>{" "}
              {entry.text}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

