"use client";

import { useState, useCallback } from "react";
import { useRouter } from "next/navigation";
import PhaseStepper from "@/components/onboarding/PhaseStepper";
import PhaseBasics from "@/components/onboarding/PhaseBasics";
import PhaseContacts from "@/components/onboarding/PhaseContacts";
import PhasePreferences from "@/components/onboarding/PhasePreferences";
import PhaseScenario from "@/components/onboarding/PhaseScenario";
import PhaseConfirm from "@/components/onboarding/PhaseConfirm";

interface OnboardingData {
  name: string;
  language: string;
  contacts: { name: string; relationship: string; phone_number: string; priority: string }[];
  deliveryInstructions: string;
  callPreferences: Record<string, string>;
  customRules: string[];
}

export default function OnboardingPage() {
  const router = useRouter();
  const [phase, setPhase] = useState(1);
  const [data, setData] = useState<OnboardingData>({
    name: "",
    language: "english",
    contacts: [],
    deliveryInstructions: "",
    callPreferences: {},
    customRules: [],
  });

  const handleBasicsComplete = useCallback(
    (basics: { name: string; language: string }) => {
      setData((prev) => ({ ...prev, name: basics.name, language: basics.language }));
      setPhase(2);
    },
    []
  );

  const handleContactsComplete = useCallback(
    async (
      contacts: { name: string; relationship: string; phone_number: string; priority: string }[]
    ) => {
      // Save contacts to backend
      for (const contact of contacts) {
        await fetch("/api/contacts", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(contact),
        });
      }
      setData((prev) => ({ ...prev, contacts }));
      setPhase(3);
    },
    []
  );

  const handlePreferencesComplete = useCallback(
    (prefs: Record<string, unknown>) => {
      setData((prev) => ({
        ...prev,
        deliveryInstructions: (prefs.delivery_instructions as string) || "",
        callPreferences: (prefs.call_preferences as Record<string, string>) || {},
        customRules: (prefs.custom_rules as string[]) || [],
      }));
      setPhase(4);
    },
    []
  );

  const handleScenarioComplete = useCallback(() => {
    setPhase(5);
  }, []);

  const handleConfirm = useCallback(async () => {
    await fetch("/api/onboarding", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: data.name,
        default_language: data.language,
        delivery_instructions: data.deliveryInstructions,
        call_preferences: data.callPreferences,
        custom_rules: data.customRules,
      }),
    });
    router.push("/dashboard");
  }, [data, router]);

  return (
    <main className="min-h-screen bg-white dark:bg-gray-950 text-gray-900 dark:text-gray-100 py-8 px-4">
      <div className="max-w-2xl mx-auto">
        <PhaseStepper current={phase} />

        {phase === 1 && <PhaseBasics onComplete={handleBasicsComplete} />}

        {phase === 2 && <PhaseContacts onComplete={handleContactsComplete} />}

        {phase === 3 && (
          <PhasePreferences onComplete={handlePreferencesComplete} />
        )}

        {phase === 4 && <PhaseScenario onComplete={handleScenarioComplete} />}

        {phase === 5 && (
          <PhaseConfirm
            ownerName={data.name}
            language={data.language}
            contactCount={data.contacts.length}
            deliveryInstructions={data.deliveryInstructions}
            callPreferences={data.callPreferences}
            onConfirm={handleConfirm}
          />
        )}
      </div>
    </main>
  );
}

"use client";

interface Props {
  ownerName: string;
  language: string;
  contactCount: number;
  deliveryInstructions: string;
  callPreferences: Record<string, string>;
  onConfirm: () => void;
}

export default function PhaseConfirm({
  ownerName,
  language,
  contactCount,
  deliveryInstructions,
  callPreferences,
  onConfirm,
}: Props) {
  return (
    <div>
      <h2 className="text-xl font-bold mb-2">Confirm Your Setup</h2>
      <p className="text-gray-500 mb-6">
        Here&apos;s everything we&apos;ve collected. Confirm to start your AI receptionist.
      </p>

      <div className="space-y-4 mb-8 max-w-md mx-auto text-left">
        <div className="bg-gray-50 dark:bg-gray-800 rounded-lg p-4">
          <div className="text-sm text-gray-500 mb-1">Name</div>
          <div className="font-medium">{ownerName || "Not set"}</div>
        </div>

        <div className="bg-gray-50 dark:bg-gray-800 rounded-lg p-4">
          <div className="text-sm text-gray-500 mb-1">Greeting Language</div>
          <div className="font-medium capitalize">{language || "english"}</div>
        </div>

        <div className="bg-gray-50 dark:bg-gray-800 rounded-lg p-4">
          <div className="text-sm text-gray-500 mb-1">Saved Contacts</div>
          <div className="font-medium">{contactCount} contact{contactCount !== 1 ? "s" : ""}</div>
        </div>

        <div className="bg-gray-50 dark:bg-gray-800 rounded-lg p-4">
          <div className="text-sm text-gray-500 mb-1">Delivery Instructions</div>
          <div className="font-medium">
            {deliveryInstructions || "No specific instructions set"}
          </div>
        </div>

        {Object.keys(callPreferences).length > 0 && (
          <div className="bg-gray-50 dark:bg-gray-800 rounded-lg p-4">
            <div className="text-sm text-gray-500 mb-1">Call Preferences</div>
            {Object.entries(callPreferences).map(([type, pref]) => (
              <div key={type} className="text-sm">
                <span className="capitalize">{type}</span>:{" "}
                <span className={pref === "decline" ? "text-red-600" : "text-green-600"}>
                  {pref}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="text-center">
        <button
          onClick={onConfirm}
          className="bg-green-600 hover:bg-green-700 text-white font-semibold py-3 px-8 rounded-lg text-lg transition-colors"
        >
          Confirm & Start
        </button>
      </div>
    </div>
  );
}

"use client";

import { useVoiceSession } from "@/hooks/useVoiceSession";
import { useCallback } from "react";

interface Props {
  onComplete: () => void;
}

export default function PhaseScenario({ onComplete }: Props) {
  const handlePhaseComplete = useCallback(
    (phase: number) => {
      if (phase === 4) onComplete();
    },
    [onComplete]
  );

  const { status, error, transcript, startSession, endSession } =
    useVoiceSession({
      mode: "onboarding",
      onboardingPhase: 4,
      onPhaseComplete: handlePhaseComplete,
    });

  const isActive = status === "connected";

  return (
    <div className="text-center">
      <h2 className="text-xl font-bold mb-2">Quick Scenario Test</h2>
      <p className="text-gray-500 mb-6">
        The AI will roleplay 2-3 quick caller scenarios so you can see how it
        handles them. Keep it short!
      </p>

      {status === "idle" && (
        <div className="space-y-3">
          <button
            onClick={startSession}
            className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-8 rounded-lg text-lg transition-colors"
          >
            Start Scenario Test
          </button>
          <div>
            <button
              onClick={onComplete}
              className="text-sm text-gray-500 hover:text-gray-700 underline"
            >
              Skip this step
            </button>
          </div>
        </div>
      )}

      {status === "connecting" && (
        <div className="text-yellow-600 font-medium">Connecting...</div>
      )}

      {isActive && (
        <div className="space-y-4">
          <div className="flex justify-center">
            <div className="w-16 h-16 bg-purple-500 rounded-full animate-pulse flex items-center justify-center">
              <svg className="w-8 h-8 text-white" fill="currentColor" viewBox="0 0 24 24">
                <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zm5-3c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z" />
              </svg>
            </div>
          </div>
          <p className="text-green-600 font-medium">Scenario test in progress...</p>
          <button onClick={endSession} className="text-sm text-gray-500 underline">
            Stop
          </button>
        </div>
      )}

      {error && <p className="text-red-600 mt-4">{error}</p>}

      {transcript.length > 0 && (
        <div className="mt-6 text-left max-w-md mx-auto space-y-2">
          {transcript.map((entry, i) => (
            <div
              key={i}
              className={`text-sm p-2 rounded ${
                entry.role === "ai"
                  ? "bg-gray-100 dark:bg-gray-800"
                  : "bg-blue-50 dark:bg-blue-900/20"
              }`}
            >
              <span className="font-medium text-xs text-gray-500">
                {entry.role === "ai" ? "AI" : "You"}:
              </span>{" "}
              {entry.text}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

"use client";

import { useVoiceSession } from "@/hooks/useVoiceSession";
import { useCallback } from "react";

interface Props {
  onComplete: (data: Record<string, unknown>) => void;
