216	  }, [phoneNumber, mode, onboardingPhase, onPhaseComplete, cleanup]);
217	
218	  const endSession = useCallback(() => {
219	    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
220	      wsRef.current.send(JSON.stringify({ type: "end_call" }));
221	    }
222	    setStatus("ended");
223	    cleanup();
224	  }, [cleanup]);
225	
226	  return {
227	    status,
228	    error,
229	    transcript,
230	    callerInfo,
231	    startSession,
232	    endSession,
233	  };
234	}
235	
236	/**
237	 * Play base64-encoded PCM16 audio through the AudioContext.
238	 */
239	function playAudio(base64Audio: string, audioContext: AudioContext) {
240	  // Decode base64 to ArrayBuffer
241	  const binary = atob(base64Audio);
242	  const bytes = new Uint8Array(binary.length);
243	  for (let i = 0; i < binary.length; i++) {
244	    bytes[i] = binary.charCodeAt(i);
245	  }
246	
247	  // Convert Int16 PCM to Float32
248	  const int16 = new Int16Array(bytes.buffer);
249	  const float32 = new Float32Array(int16.length);
250	  for (let i = 0; i < int16.length; i++) {
251	    float32[i] = int16[i] / 32768;
252	  }
253	
254	  // Create audio buffer and play
255	  const audioBuffer = audioContext.createBuffer(1, float32.length, 24000);
256	  audioBuffer.getChannelData(0).set(float32);
257	
258	  const source = audioContext.createBufferSource();
259	  source.buffer = audioBuffer;
260	  source.connect(audioContext.destination);
261	  source.start();
262	}
