1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	
5	interface CallLog {
6	  call_id: number;
7	  phone_number: string;
8	  caller_name: string | null;
9	  message: string;
10	  conversation_history: { role: string; text: string; timestamp: number }[];
11	  type: string;
12	  priority: "high" | "medium" | "low";
13	  language_states: string[];
14	  timestamp: number;
15	  action_taken: string;
16	  owner_verified_type: string | null;
17	}
18	
19	const PRIORITY_ORDER: Record<string, number> = {
20	  high: 0,
21	  medium: 1,
22	  low: 2,
23	};
24	
25	function sortByPriority(calls: CallLog[]): CallLog[] {
26	  return [...calls].sort(
27	    (a, b) =>
28	      (PRIORITY_ORDER[a.priority] ?? 3) - (PRIORITY_ORDER[b.priority] ?? 3) ||
29	      b.timestamp - a.timestamp
30	  );
31	}
32	
33	export type { CallLog };
34	
35	export function useDashboardWS() {
36	  const [calls, setCalls] = useState<CallLog[]>([]);
37	  const [connected, setConnected] = useState(false);
38	  const wsRef = useRef<WebSocket | null>(null);
39	  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null);
40	
41	  const connect = useCallback(() => {
42	    const protocol = window.location.protocol === "https:" ? "wss:" : "ws:";
43	    const ws = new WebSocket(`${protocol}//${window.location.host}/ws/dashboard`);
44	    wsRef.current = ws;
45	
46	    ws.onopen = () => setConnected(true);
47	
48	    ws.onmessage = (event) => {
49	      const msg = JSON.parse(event.data);
50	
51	      if (msg.type === "full_sync") {
52	        setCalls(sortByPriority(msg.calls || []));
53	      } else if (msg.type === "new_call") {
54	        setCalls((prev) => sortByPriority([msg.call, ...prev]));
55	      } else if (msg.type === "call_updated") {
56	        setCalls((prev) =>
57	          sortByPriority(
58	            prev.map((c) => (c.call_id === msg.call.call_id ? msg.call : c))
59	          )
60	        );
61	      }
62	    };
63	
64	    ws.onclose = () => {
65	      setConnected(false);
66	      reconnectTimeoutRef.current = setTimeout(connect, 3000);
67	    };
68	
69	    ws.onerror = () => ws.close();
70	  }, []);
71	
72	  useEffect(() => {
73	    connect();
74	    return () => {
75	      if (reconnectTimeoutRef.current) clearTimeout(reconnectTimeoutRef.current);
76	      wsRef.current?.close();
77	    };
78	  }, [connect]);
79	
80	  const sendAction = useCallback(
81	    (action: Record<string, unknown>) => {
82	      if (wsRef.current?.readyState === WebSocket.OPEN) {
83	        wsRef.current.send(JSON.stringify(action));
84	      }
85	    },
86	    []
87	  );
88	
89	  return { calls, connected, sendAction };
90	}
