"use client";

import { useState } from "react";

interface ContactRow {
  name: string;
  relationship: string;
  phone_number: string;
  priority: "high" | "medium" | "low";
}

interface Props {
  onComplete: (contacts: ContactRow[]) => void;
}

const EMPTY_ROW: ContactRow = {
  name: "",
  relationship: "",
  phone_number: "",
  priority: "medium",
};

export default function PhaseContacts({ onComplete }: Props) {
  const [contacts, setContacts] = useState<ContactRow[]>([{ ...EMPTY_ROW }]);

  const updateRow = (index: number, field: keyof ContactRow, value: string) => {
    setContacts((prev) =>
      prev.map((c, i) => (i === index ? { ...c, [field]: value } : c))
    );
  };

  const addRow = () => setContacts((prev) => [...prev, { ...EMPTY_ROW }]);

  const removeRow = (index: number) => {
    if (contacts.length <= 1) return;
    setContacts((prev) => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = () => {
    const valid = contacts.filter((c) => c.name.trim() && c.phone_number.trim());
    onComplete(valid);
  };

  return (
    <div>
      <h2 className="text-xl font-bold mb-2">Add Your Contacts</h2>
      <p className="text-gray-500 mb-6">
        Add people whose calls should be handled specially. High priority = bypass
        directly, Medium = urgent notify, Low = normal log.
      </p>

      <div className="space-y-3 mb-6">
        {contacts.map((contact, i) => (
          <div
            key={i}
            className="grid grid-cols-12 gap-2 items-center bg-gray-50 dark:bg-gray-800 p-3 rounded-lg"
          >
            <input
              type="text"
              placeholder="Name"
              value={contact.name}
              onChange={(e) => updateRow(i, "name", e.target.value)}
              className="col-span-3 text-sm px-3 py-2 border rounded dark:bg-gray-900 dark:border-gray-600"
            />
            <input
              type="text"
              placeholder="Relationship"
              value={contact.relationship}
              onChange={(e) => updateRow(i, "relationship", e.target.value)}
              className="col-span-3 text-sm px-3 py-2 border rounded dark:bg-gray-900 dark:border-gray-600"
            />
            <input
              type="tel"
              placeholder="Phone"
              value={contact.phone_number}
              onChange={(e) => updateRow(i, "phone_number", e.target.value)}
              className="col-span-3 text-sm px-3 py-2 border rounded dark:bg-gray-900 dark:border-gray-600"
            />
            <select
              value={contact.priority}
              onChange={(e) => updateRow(i, "priority", e.target.value)}
              className="col-span-2 text-sm px-2 py-2 border rounded dark:bg-gray-900 dark:border-gray-600"
            >
              <option value="high">High</option>
              <option value="medium">Medium</option>
              <option value="low">Low</option>
            </select>
            <button
              onClick={() => removeRow(i)}
              className="col-span-1 text-red-500 hover:text-red-700 text-sm text-center"
              disabled={contacts.length <= 1}
            >
              ✕
            </button>
          </div>
        ))}
      </div>

      <div className="flex gap-3">
        <button
          onClick={addRow}
          className="text-sm text-blue-600 hover:text-blue-700 font-medium"
        >
          + Add Contact
        </button>
        <div className="flex-1" />
        <button
          onClick={() => onComplete([])}
          className="text-sm text-gray-500 hover:text-gray-700 px-4 py-2"
        >
          Skip
        </button>
        <button
          onClick={handleSubmit}
          className="bg-blue-600 hover:bg-blue-700 text-white font-medium px-6 py-2 rounded-lg text-sm transition-colors"
        >
          Next
        </button>
      </div>
    </div>
  );
}

