import asyncio
import json
import os
from dotenv import load_dotenv
load_dotenv()

import websockets

async def test_connection():
    url = 'wss://api.openai.com/v1/realtime?model=gpt-4o-realtime-preview'
    api_key = os.environ.get('OPENAI_API_KEY', '')
    print(f'API key present: {bool(api_key)}')
    print(f'API key starts with: {api_key[:12]}...')

    try:
        ws = await websockets.connect(
            url,
            additional_headers={
                'Authorization': f'Bearer {api_key}',
            },
        )
        print('Connected successfully!')

        # Wait for session.created event
        msg = await asyncio.wait_for(ws.recv(), timeout=10)
        event = json.loads(msg)
        print(f'Received event: {event.get(\"type\", \"unknown\")}')

        if event.get('type') == 'session.created':
            print('Session created! GA API connection works.')
            session = event.get('session', {})
            print(f'  Session ID: {session.get(\"id\", \"N/A\")}')
            print(f'  Model: {session.get(\"model\", \"N/A\")}')

        # Send session.update with GA format
        session_config = {
            'type': 'session.update',
            'session': {
                'type': 'realtime',
                'instructions': 'You are a friendly AI receptionist. Say hello briefly.',
                'output_modalities': ['audio'],
                'audio': {
                    'input': {
                        'format': {'type': 'audio/pcm', 'rate': 24000},
                        'transcription': {'model': 'whisper-1'},
                        'turn_detection': {
                            'type': 'server_vad',
                            'threshold': 0.5,
                            'prefix_padding_ms': 300,
                            'silence_duration_ms': 700,
                        },
                    },
                    'output': {
                        'format': {'type': 'audio/pcm', 'rate': 24000},
                        'voice': 'alloy',
                    },
                },
                'tools': [{
                    'type': 'function',
                    'name': 'classify_caller',
                    'description': 'Classify the caller type',
                    'parameters': {
                        'type': 'object',
                        'properties': {
                            'caller_type': {'type': 'string'},
                        },
                        'required': ['caller_type'],
                    },
                }],
                'tool_choice': 'auto',
            },
        }
        await ws.send(json.dumps(session_config))
        print('Sent session.update...')

        # Wait for session.updated confirmation
        msg = await asyncio.wait_for(ws.recv(), timeout=10)
        event = json.loads(msg)
        print(f'Received event: {event.get(\"type\", \"unknown\")}')

        if event.get('type') == 'session.updated':
            print('Session updated successfully! Full GA config accepted.')
        elif event.get('type') == 'error':
            err = event.get('error', {})
            print(f'ERROR: {err.get(\"message\", \"unknown\")}')
            print(f'Code: {err.get(\"code\", \"N/A\")}')

        await ws.close()
        print('Test complete - connection closed cleanly.')

    except Exception as e:
        print(f'FAILED: {type(e).__name__}: {e}')

asyncio.run(test_connection())
" 2>&1

