3	import { useState, useCallback, useEffect } from "react";
4	import { useRouter } from "next/navigation";
5	import PhaseStepper from "@/components/onboarding/PhaseStepper";
6	import PhaseBasics from "@/components/onboarding/PhaseBasics";
7	import PhaseContacts from "@/components/onboarding/PhaseContacts";
