9	import PhaseScenario from "@/components/onboarding/PhaseScenario";
10	import PhaseConfirm from "@/components/onboarding/PhaseConfirm";
11	
12	interface OnboardingData {
13	  name: string;
14	  language: string;
15	  contacts: { name: string; relationship: string; phone_number: string; priority: string }[];
16	  deliveryInstructions: string;
17	  callPreferences: Record<string, string>;
18	  customRules: string[];
19	}
20	
21	export default function OnboardingPage() {
22	  const router = useRouter();
23	  const [loading, setLoading] = useState(true);
24	  const [phase, setPhase] = useState(1);
25	  const [data, setData] = useState<OnboardingData>({
26	    name: "",
27	    language: "english",
28	    contacts: [],
29	    deliveryInstructions: "",
30	    callPreferences: {},
31	    customRules: [],
32	  });
33	
34	  useEffect(() => {
35	    fetch("/api/status")
36	      .then((r) => r.json())
37	      .then((d) => {
38	        if (d.onboarding_complete) router.replace("/dashboard");
39	        else setLoading(false);
40	      })
41	      .catch(() => setLoading(false));
42	  }, [router]);
43	
44	  const handleBasicsComplete = useCallback(
45	    (basics: { name: string; language: string }) => {
46	      setData((prev) => ({ ...prev, name: basics.name, language: basics.language }));
47	      setPhase(2);
48	    },
49	    []
50	  );
51	
52	  const handleContactsComplete = useCallback(
53	    async (
54	      contacts: { name: string; relationship: string; phone_number: string; priority: string }[]
55	    ) => {
56	      // Save contacts to backend
57	      for (const contact of contacts) {
58	        await fetch("/api/contacts", {
59	          method: "POST",
60	          headers: { "Content-Type": "application/json" },
61	          body: JSON.stringify(contact),
62	        });
63	      }
64	      setData((prev) => ({ ...prev, contacts }));
65	      setPhase(3);
66	    },
67	    []
68	  );
69	
70	  const handlePreferencesComplete = useCallback(
71	    (prefs: Record<string, unknown>) => {
72	      setData((prev) => ({
73	        ...prev,
74	        deliveryInstructions: (prefs.delivery_instructions as string) || "",
75	        callPreferences: (prefs.call_preferences as Record<string, string>) || {},
76	        customRules: (prefs.custom_rules as string[]) || [],
77	      }));
78	      setPhase(4);
79	    },
80	    []
81	  );
82	
83	  const handleScenarioComplete = useCallback(() => {
84	    setPhase(5);
85	  }, []);
86	
87	  const handleConfirm = useCallback(async () => {
88	    await fetch("/api/onboarding", {
89	      method: "POST",
90	      headers: { "Content-Type": "application/json" },
91	      body: JSON.stringify({
92	        name: data.name,
93	        default_language: data.language,
94	        delivery_instructions: data.deliveryInstructions,
