"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { getWsBaseUrl } from "./wsUrl";

export interface TranscriptEntry {
  role: "caller" | "ai";
  text: string;
}

export interface CallerInfo {
  caller_type: string;
  caller_name: string | null;
  priority: string;
  language: string;
  is_scammer: boolean;
}

interface VoiceSessionOptions {
  phoneNumber?: string;
  mode?: "call" | "onboarding";
  onboardingPhase?: number;
  onPhaseComplete?: (phase: number, data?: Record<string, unknown>) => void;
}

type SessionStatus =
  | "idle"
  | "connecting"
  | "connected"
  | "blocked"
  | "bypass"
  | "ended"
  | "error";

export function useVoiceSession(options: VoiceSessionOptions = {}) {
  const {
    phoneNumber = "",
    mode = "call",
    onboardingPhase = 0,
    onPhaseComplete,
  } = options;

  const [status, setStatus] = useState<SessionStatus>("idle");
  const [error, setError] = useState<string | null>(null);
  const [transcript, setTranscript] = useState<TranscriptEntry[]>([]);
  const [callerInfo, setCallerInfo] = useState<CallerInfo | null>(null);

  const wsRef = useRef<WebSocket | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const workletNodeRef = useRef<AudioWorkletNode | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const playbackTimeRef = useRef<number>(0);
  const isActiveRef = useRef(false);

  const cleanup = useCallback(() => {
    isActiveRef.current = false;

    if (workletNodeRef.current) {
      workletNodeRef.current.disconnect();
      workletNodeRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close().catch(() => {});
      audioContextRef.current = null;
    }
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
    playbackTimeRef.current = 0;
  }, []);

  // Cleanup on unmount
  useEffect(() => {
    return () => cleanup();
  }, [cleanup]);

  const startSession = useCallback(async () => {
    cleanup();
    setStatus("connecting");
    setError(null);
    setTranscript([]);
    setCallerInfo(null);
    isActiveRef.current = true;

    try {
      // 1. Get mic permission
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          sampleRate: 24000,
          channelCount: 1,
          echoCancellation: true,
          noiseSuppression: true,
        },
      });
      streamRef.current = stream;

      // 2. Create AudioContext at 24kHz
      const audioContext = new AudioContext({ sampleRate: 24000 });
      audioContextRef.current = audioContext;

      // 3. Load AudioWorklet
      await audioContext.audioWorklet.addModule("/audio-processor.js");
      const source = audioContext.createMediaStreamSource(stream);
      const workletNode = new AudioWorkletNode(
        audioContext,
        "audio-capture-processor"
      );
      workletNodeRef.current = workletNode;

      // 4. Connect to backend WebSocket
      const wsUrl = `${getWsBaseUrl()}/ws/voice`;
      const ws = new WebSocket(wsUrl);
      wsRef.current = ws;

      ws.onopen = () => {
        // Send initial message
        ws.send(
          JSON.stringify({
            type: mode === "onboarding" ? "start_onboarding" : "start_call",
            phone_number: phoneNumber,
            phase: onboardingPhase,
          })
        );
      };

      // 5. Pipe mic audio to WebSocket
      workletNode.port.onmessage = (event) => {
        if (
          !isActiveRef.current ||
          !ws ||
          ws.readyState !== WebSocket.OPEN
        )
          return;

        const { data } = event.data;
        // Convert ArrayBuffer to base64
        const bytes = new Uint8Array(data);
        let binary = "";
        for (let i = 0; i < bytes.byteLength; i++) {
          binary += String.fromCharCode(bytes[i]);
        }
        const base64 = btoa(binary);
        ws.send(JSON.stringify({ type: "audio_data", audio: base64 }));
      };

      source.connect(workletNode);
      workletNode.connect(audioContext.destination); // needed for worklet to process

      // 6. Handle incoming messages
      ws.onmessage = (event) => {
        const msg = JSON.parse(event.data);

        switch (msg.type) {
          case "status":
            if (msg.status === "connected") {
              setStatus("connected");
            } else if (msg.status === "bypass") {
              setStatus("bypass");
            }
            break;

          case "blocked":
            setStatus("blocked");
            setError(msg.reason || "This number has been blocked.");
            cleanup();
            break;

          case "audio_data":
            playAudio(msg.audio, audioContext);
            break;

          case "transcript":
            setTranscript((prev) => [
              ...prev,
              { role: msg.role, text: msg.text },
            ]);
            break;

          case "caller_info":
            setCallerInfo(msg);
            break;

          case "onboarding_phase_complete":
            onPhaseComplete?.(msg.phase, msg.data);
            break;

          case "error":
            setError(msg.message);
            setStatus("error");
            break;
        }
      };

      ws.onclose = () => {
        if (isActiveRef.current) {
          setStatus("ended");
        }
      };

      ws.onerror = () => {
        setError("WebSocket connection failed");
        setStatus("error");
      };
    } catch (err) {
      const message =
        err instanceof Error ? err.message : "Failed to start voice session";
      setError(message);
      setStatus("error");
      cleanup();
    }
  }, [phoneNumber, mode, onboardingPhase, onPhaseComplete, cleanup]);

  const endSession = useCallback(() => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: "end_call" }));
    }
    setStatus("ended");
    cleanup();
  }, [cleanup]);

  return {
    status,
    error,
    transcript,
    callerInfo,
    startSession,
    endSession,
  };
}

/**
 * Play base64-encoded PCM16 audio through the AudioContext.
 */
function playAudio(base64Audio: string, audioContext: AudioContext) {
  // Decode base64 to ArrayBuffer
  const binary = atob(base64Audio);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }

  // Convert Int16 PCM to Float32
  const int16 = new Int16Array(bytes.buffer);
  const float32 = new Float32Array(int16.length);
  for (let i = 0; i < int16.length; i++) {
    float32[i] = int16[i] / 32768;
  }

  // Create audio buffer and play
  const audioBuffer = audioContext.createBuffer(1, float32.length, 24000);
  audioBuffer.getChannelData(0).set(float32);

  const source = audioContext.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(audioContext.destination);
  source.start();
}

