3	import { useCallback, useEffect, useRef, useState } from "react";
4	import { getWsBaseUrl } from "./wsUrl";
5	
6	export interface TranscriptEntry {
7	  role: "caller" | "ai";
8	  text: string;
9	}
10	
11	export interface CallerInfo {
12	  caller_type: string;
13	  caller_name: string | null;
14	  priority: string;
15	  language: string;
16	  is_scammer: boolean;
17	}
18	
19	interface VoiceSessionOptions {
20	  phoneNumber?: string;
21	  mode?: "call" | "onboarding";
22	  onboardingPhase?: number;
23	  onPhaseComplete?: (phase: number, data?: Record<string, unknown>) => void;
24	}
25	
26	type SessionStatus =
27	  | "idle"
28	  | "connecting"
29	  | "connected"
30	  | "blocked"
31	  | "bypass"
32	  | "ended"
33	  | "error";
34	
35	export function useVoiceSession(options: VoiceSessionOptions = {}) {
36	  const {
37	    phoneNumber = "",
38	    mode = "call",
39	    onboardingPhase = 0,
40	    onPhaseComplete,
41	  } = options;
42	
43	  const [status, setStatus] = useState<SessionStatus>("idle");
44	  const [error, setError] = useState<string | null>(null);
45	  const [transcript, setTranscript] = useState<TranscriptEntry[]>([]);
46	  const [callerInfo, setCallerInfo] = useState<CallerInfo | null>(null);
47	
48	  const wsRef = useRef<WebSocket | null>(null);
49	  const audioContextRef = useRef<AudioContext | null>(null);
50	  const workletNodeRef = useRef<AudioWorkletNode | null>(null);
51	  const streamRef = useRef<MediaStream | null>(null);
52	  const playbackTimeRef = useRef<number>(0);
53	  const isActiveRef = useRef(false);
54	
55	  const cleanup = useCallback(() => {
56	    isActiveRef.current = false;
57	
58	    if (workletNodeRef.current) {
59	      workletNodeRef.current.disconnect();
60	      workletNodeRef.current = null;
61	    }
62	    if (streamRef.current) {
63	      streamRef.current.getTracks().forEach((t) => t.stop());
64	      streamRef.current = null;
65	    }
66	    if (audioContextRef.current) {
67	      audioContextRef.current.close().catch(() => {});
68	      audioContextRef.current = null;
69	    }
70	    if (wsRef.current) {
71	      wsRef.current.close();
72	      wsRef.current = null;
73	    }
74	    playbackTimeRef.current = 0;
75	  }, []);
76	
77	  // Cleanup on unmount
78	  useEffect(() => {
79	    return () => cleanup();
80	  }, [cleanup]);
81	
82	  const startSession = useCallback(async () => {
83	    cleanup();
84	    setStatus("connecting");
85	    setError(null);
86	    setTranscript([]);
87	    setCallerInfo(null);
88	    isActiveRef.current = true;
89	
90	    try {
91	      // 1. Get mic permission
92	      const stream = await navigator.mediaDevices.getUserMedia({
93	        audio: {
94	          sampleRate: 24000,
95	          channelCount: 1,
96	          echoCancellation: true,
97	          noiseSuppression: true,
98	        },
99	      });
100	      streamRef.current = stream;
101	
102	      // 2. Create AudioContext at 24kHz
103	      const audioContext = new AudioContext({ sampleRate: 24000 });
104	      audioContextRef.current = audioContext;
105	
106	      // 3. Load AudioWorklet
107	      await audioContext.audioWorklet.addModule("/audio-processor.js");
108	      const source = audioContext.createMediaStreamSource(stream);
109	      const workletNode = new AudioWorkletNode(
110	        audioContext,
111	        "audio-capture-processor"
112	      );
113	      workletNodeRef.current = workletNode;
114	
115	      // 4. Connect to backend WebSocket
116	      const wsUrl = `${getWsBaseUrl()}/ws/voice`;
117	      const ws = new WebSocket(wsUrl);
118	      wsRef.current = ws;
119	
120	      ws.onopen = () => {
121	        // Send initial message
122	        ws.send(
123	          JSON.stringify({
124	            type: mode === "onboarding" ? "start_onboarding" : "start_call",
125	            phone_number: phoneNumber,
126	            phase: onboardingPhase,
127	          })
128	        );
129	      };
130	
131	      // 5. Pipe mic audio to WebSocket
132	      workletNode.port.onmessage = (event) => {
133	        if (
134	          !isActiveRef.current ||
135	          !ws ||
136	          ws.readyState !== WebSocket.OPEN
137	        )
138	          return;
139	
140	        const { data } = event.data;
141	        // Convert ArrayBuffer to base64
142	        const bytes = new Uint8Array(data);
143	        let binary = "";
144	        for (let i = 0; i < bytes.byteLength; i++) {
145	          binary += String.fromCharCode(bytes[i]);
146	        }
147	        const base64 = btoa(binary);
148	        ws.send(JSON.stringify({ type: "audio_data", audio: base64 }));
149	      };
150	
151	      source.connect(workletNode);
152	      workletNode.connect(audioContext.destination); // needed for worklet to process
153	
154	      // 6. Handle incoming messages
155	      ws.onmessage = (event) => {
156	        const msg = JSON.parse(event.data);
157	
158	        switch (msg.type) {
159	          case "status":
160	            if (msg.status === "connected") {
161	              setStatus("connected");
162	            } else if (msg.status === "bypass") {
163	              setStatus("bypass");
164	            }
165	            break;
166	
167	          case "blocked":
168	            setStatus("blocked");
169	            setError(msg.reason || "This number has been blocked.");
170	            cleanup();
171	            break;
172	
173	          case "audio_data":
174	            playAudio(msg.audio, audioContext);
175	            break;
176	
177	          case "transcript":
178	            setTranscript((prev) => [
179	              ...prev,
180	              { role: msg.role, text: msg.text },
181	            ]);
182	            break;
183	
184	          case "caller_info":
185	            setCallerInfo(msg);
186	            break;
187	
188	          case "onboarding_phase_complete":
189	            onPhaseComplete?.(msg.phase, msg.data);
190	            break;
191	
192	          case "error":
193	            setError(msg.message);
194	            setStatus("error");
195	            break;
196	        }
197	      };
198	
199	      ws.onclose = () => {
200	        if (isActiveRef.current) {
201	          setStatus("ended");
202	        }
203	      };
204	
205	      ws.onerror = () => {
206	        setError("WebSocket connection failed");
207	        setStatus("error");
208	      };
209	    } catch (err) {
210	      const message =
211	        err instanceof Error ? err.message : "Failed to start voice session";
212	      setError(message);
213	      setStatus("error");
214	      cleanup();
215	    }
216	  }, [phoneNumber, mode, onboardingPhase, onPhaseComplete, cleanup]);
217	
218	  const endSession = useCallback(() => {
219	    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
220	      wsRef.current.send(JSON.stringify({ type: "end_call" }));
221	    }
222	    setStatus("ended");
223	    cleanup();
224	  }, [cleanup]);
225	
226	  return {
227	    status,
228	    error,
229	    transcript,
230	    callerInfo,
231	    startSession,
232	    endSession,
233	  };
234	}
235	
236	/**
237	 * Play base64-encoded PCM16 audio through the AudioContext.
238	 */
239	function playAudio(base64Audio: string, audioContext: AudioContext) {
240	  // Decode base64 to ArrayBuffer
241	  const binary = atob(base64Audio);
242	  const bytes = new Uint8Array(binary.length);
243	  for (let i = 0; i < binary.length; i++) {
244	    bytes[i] = binary.charCodeAt(i);
245	  }
246	
247	  // Convert Int16 PCM to Float32
248	  const int16 = new Int16Array(bytes.buffer);
249	  const float32 = new Float32Array(int16.length);
250	  for (let i = 0; i < int16.length; i++) {
251	    float32[i] = int16[i] / 32768;
252	  }
253	
254	  // Create audio buffer and play
255	  const audioBuffer = audioContext.createBuffer(1, float32.length, 24000);
256	  audioBuffer.getChannelData(0).set(float32);
257	
258	  const source = audioContext.createBufferSource();
259	  source.buffer = audioBuffer;
260	  source.connect(audioContext.destination);
261	  source.start();
262	}
