"use client";

import { useState } from "react";
import { useVoiceSession, TranscriptEntry } from "@/hooks/useVoiceSession";

export default function CallInterface() {
  const [phoneNumber, setPhoneNumber] = useState("");

  const { status, error, transcript, callerInfo, startSession, endSession } =
    useVoiceSession({
      phoneNumber,
      mode: "call",
    });

  const isInCall = status === "connected" || status === "bypass";

  const handleStartCall = () => {
    if (!phoneNumber.trim()) return;
    startSession();
  };

  return (
    <div className="max-w-2xl mx-auto p-6">
      <h1 className="text-2xl font-bold mb-6">Simulate Incoming Call</h1>

      {/* Phone Number Input */}
      <div className="mb-6">
        <label className="block text-sm font-medium mb-2" htmlFor="phone">
          Caller Phone Number
        </label>
        <input
          id="phone"
          type="tel"
          value={phoneNumber}
          onChange={(e) => setPhoneNumber(e.target.value)}
          placeholder="Enter phone number (e.g., 9876543210)"
          className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 text-lg dark:bg-gray-800 dark:border-gray-600"
          disabled={isInCall}
        />
      </div>

      {/* Call Controls */}
      <div className="flex gap-4 mb-6">
        {!isInCall && status !== "connecting" && (
          <button
            onClick={handleStartCall}
            disabled={!phoneNumber.trim()}
            className="flex-1 bg-green-600 hover:bg-green-700 disabled:bg-gray-400 text-white font-semibold py-3 px-6 rounded-lg transition-colors text-lg"
          >
            📞 Start Call
          </button>
        )}
        {status === "connecting" && (
          <button
            disabled
            className="flex-1 bg-yellow-600 text-white font-semibold py-3 px-6 rounded-lg text-lg"
          >
            Connecting...
          </button>
        )}
        {isInCall && (
          <button
            onClick={endSession}
            className="flex-1 bg-red-600 hover:bg-red-700 text-white font-semibold py-3 px-6 rounded-lg transition-colors text-lg"
          >
            End Call
          </button>
        )}
      </div>

      {/* Status Indicator */}
      <StatusBadge status={status} error={error} />

      {/* Caller Info (from AI classification) */}
      {callerInfo && (
        <div className="mb-6 p-4 bg-blue-50 dark:bg-blue-900/20 rounded-lg border border-blue-200 dark:border-blue-800">
          <h3 className="font-semibold text-sm text-blue-600 dark:text-blue-400 mb-2">
            AI Classification
          </h3>
          <div className="grid grid-cols-2 gap-2 text-sm">
            <div>
              <span className="text-gray-500">Type:</span>{" "}
              <span className="font-medium">{callerInfo.caller_type}</span>
            </div>
            <div>
              <span className="text-gray-500">Priority:</span>{" "}
              <PriorityBadge priority={callerInfo.priority} />
            </div>
            {callerInfo.caller_name && (
              <div>
                <span className="text-gray-500">Name:</span>{" "}
                <span className="font-medium">{callerInfo.caller_name}</span>
              </div>
            )}
            <div>
              <span className="text-gray-500">Language:</span>{" "}
              <span className="font-medium">{callerInfo.language}</span>
            </div>
            {callerInfo.is_scammer && (
              <div className="col-span-2 text-red-600 font-bold">
                ⚠️ SCAMMER DETECTED — Number flagged
              </div>
            )}
          </div>
        </div>
      )}

      {/* Live Transcript */}
      {transcript.length > 0 && (
        <div className="border border-gray-200 dark:border-gray-700 rounded-lg overflow-hidden">
          <h3 className="font-semibold text-sm px-4 py-2 bg-gray-50 dark:bg-gray-800 border-b border-gray-200 dark:border-gray-700">
