    </div>
  );
}

function StatusBadge({
  status,
  error,
}: {
  status: string;
  error: string | null;
}) {
  const config: Record<string, { color: string; text: string }> = {
    idle: { color: "bg-gray-100 text-gray-600", text: "Ready" },
    connecting: {
      color: "bg-yellow-100 text-yellow-700",
      text: "Connecting...",
    },
    connected: {
      color: "bg-green-100 text-green-700",
      text: "In Call — AI is listening",
    },
    bypass: {
      color: "bg-purple-100 text-purple-700",
      text: "High Priority — Bypassing to owner",
    },
    blocked: { color: "bg-red-100 text-red-700", text: "Number Blocked" },
    ended: { color: "bg-gray-100 text-gray-600", text: "Call Ended" },
    error: { color: "bg-red-100 text-red-700", text: error || "Error" },
  };

  const { color, text } = config[status] || config.idle;

  return (
    <div className={`mb-6 px-4 py-2 rounded-lg text-sm font-medium ${color}`}>
      {text}
    </div>
  );
}

function PriorityBadge({ priority }: { priority: string }) {
  const colors: Record<string, string> = {
    high: "bg-red-100 text-red-700",
    medium: "bg-yellow-100 text-yellow-700",
    low: "bg-gray-100 text-gray-600",
  };
  return (
    <span
      className={`inline-block px-2 py-0.5 rounded text-xs font-medium ${colors[priority] || colors.low}`}
    >
      {priority}
    </span>
  );
}

function TranscriptBubble({ entry }: { entry: TranscriptEntry }) {
  const isCaller = entry.role === "caller";
  return (
    <div className={`flex ${isCaller ? "justify-end" : "justify-start"}`}>
      <div
        className={`max-w-[75%] px-4 py-2 rounded-2xl text-sm ${
