          !ws ||
          ws.readyState !== WebSocket.OPEN
        )
          return;

        const { data } = event.data;
        const bytes = new Uint8Array(data);
        let binary = "";
        for (let i = 0; i < bytes.byteLength; i++) {
          binary += String.fromCharCode(bytes[i]);
        }
        const base64 = btoa(binary);
        ws.send(JSON.stringify({ type: "audio_data", audio: base64 }));
      };

      source.connect(workletNode);
      workletNode.connect(audioContext.destination);

      ws.onmessage = (event) => {
        const msg = JSON.parse(event.data);

        switch (msg.type) {
          case "status":
            if (msg.status === "connected") {
              setStatus("connected");
            } else if (msg.status === "bypass") {
              setStatus("bypass");
            }
            break;

          case "blocked":
            setStatus("blocked");
            setError(msg.reason || "This number has been blocked.");
            cleanup();
            break;

          case "audio_data":
            setIsSpeaking(true);
            playAudioQueued(msg.audio, audioContext, playbackTimeRef, scheduledSourcesRef);
            break;

          case "audio_done":
            setIsSpeaking(false);
            break;

          case "speech_started":
            cancelQueuedAudio();
            break;

          case "transcript":
            setTranscript((prev) => [
              ...prev,
              { role: msg.role, text: msg.text },
            ]);
            break;

          case "caller_info":
            setCallerInfo(msg);
            break;

          case "onboarding_phase_complete":
            onPhaseComplete?.(msg.phase, msg.data);
            break;

          case "error":
            setError(msg.message);
            setStatus("error");
