"use client";

interface VoiceOrbProps {
  state: "idle" | "connecting" | "listening" | "speaking";
  size?: "sm" | "md" | "lg";
}

export default function VoiceOrb({ state, size = "lg" }: VoiceOrbProps) {
  const sizeMap = { sm: 80, md: 120, lg: 160 };
  const px = sizeMap[size];

  return (
    <div className="relative flex items-center justify-center" style={{ width: px * 1.8, height: px * 1.8 }}>
      {/* Outer rings — only when speaking */}
      {state === "speaking" && (
        <>
          <div
            className="absolute rounded-full bg-blue-400/10 animate-[orb-ring_2s_ease-out_infinite]"
            style={{ width: px * 1.6, height: px * 1.6 }}
          />
          <div
            className="absolute rounded-full bg-blue-400/15 animate-[orb-ring_2s_ease-out_infinite_0.5s]"
            style={{ width: px * 1.3, height: px * 1.3 }}
          />
        </>
      )}

      {/* Glow behind orb */}
      <div
        className={`absolute rounded-full blur-2xl transition-opacity duration-500 ${
          state === "speaking"
            ? "bg-blue-500/30 opacity-100"
            : state === "listening"
              ? "bg-emerald-500/20 opacity-100"
              : "bg-gray-500/10 opacity-50"
        }`}
        style={{ width: px * 1.2, height: px * 1.2 }}
      />

      {/* Main orb */}
      <div
        className={`relative z-10 rounded-full flex items-center justify-center shadow-2xl transition-all duration-300 ${
          state === "speaking"
            ? "bg-gradient-to-br from-blue-400 via-indigo-500 to-purple-600 animate-[orb-speak_1s_ease-in-out_infinite]"
            : state === "listening"
              ? "bg-gradient-to-br from-emerald-400 via-teal-500 to-cyan-600 animate-[orb-listen_2.5s_ease-in-out_infinite]"
              : state === "connecting"
                ? "bg-gradient-to-br from-amber-400 via-orange-500 to-red-500 animate-pulse"
                : "bg-gradient-to-br from-gray-400 via-gray-500 to-gray-600"
        }`}
        style={{ width: px, height: px }}
      >
        {/* Inner highlight */}
        <div
          className="absolute rounded-full bg-white/10"
          style={{ width: px * 0.7, height: px * 0.7, top: px * 0.08, left: px * 0.15 }}
        />

        {/* Icon */}
        <svg
          className="relative z-10 text-white/90"
          style={{ width: px * 0.3, height: px * 0.3 }}
          fill="currentColor"
          viewBox="0 0 24 24"
        >
          {state === "speaking" ? (
            <path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z" />
          ) : (
            <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zm5-3c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z" />
          )}
        </svg>
      </div>
    </div>
  );
}

