const PHASES = [
  { num: 1, label: "Basics" },
  { num: 2, label: "Contacts" },
  { num: 3, label: "Preferences" },
  { num: 4, label: "Scenario" },
  { num: 5, label: "Confirm" },
];

export default function PhaseStepper({ current }: { current: number }) {
  return (
    <div className="flex items-center justify-center gap-1 mb-8">
