import { useVoiceSession } from "@/hooks/useVoiceSession";
import { useCallback } from "react";
import VoiceOrb from "@/components/VoiceOrb";

interface Props {
  onComplete: (data: { name: string; language: string }) => void;
}

export default function PhaseBasics({ onComplete }: Props) {
  const handlePhaseComplete = useCallback(
    (phase: number, data?: Record<string, unknown>) => {
      if (phase === 1 && data) {
        onComplete({
          name: (data.name as string) || "",
          language: (data.language as string) || "english",
        });
      }
    },
    [onComplete]
  );

  const { status, error, transcript, isSpeaking, startSession, endSession } =
    useVoiceSession({
      mode: "onboarding",
      onboardingPhase: 1,
      onPhaseComplete: handlePhaseComplete,
    });

  const isActive = status === "connected";
  const lastAiMessage = [...transcript].reverse().find((t) => t.role === "ai")?.text;

  const orbState = !isActive
    ? status === "connecting" ? "connecting" : "idle"
    : isSpeaking ? "speaking" : "listening";

  return (
    <div className="flex flex-col items-center min-h-[60vh] justify-center">
      {/* Idle / Start state */}
      {status === "idle" && (
        <div className="flex flex-col items-center gap-6">
          <VoiceOrb state="idle" />
          <div className="text-center">
            <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
              Let&apos;s get started
            </h2>
            <p className="text-gray-500 dark:text-gray-400 text-sm max-w-xs mb-6">
              Tap the button below and tell the AI your name and preferred language.
            </p>
          </div>
          <button
            onClick={startSession}
            className="bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-10 rounded-full text-base transition-all hover:shadow-lg active:scale-95"
          >
            Start
          </button>
        </div>
      )}

      {/* Connecting */}
      {status === "connecting" && (
        <div className="flex flex-col items-center gap-6">
          <VoiceOrb state="connecting" />
          <p className="text-amber-600 dark:text-amber-400 font-medium text-sm">
            Connecting...
          </p>
        </div>
      )}

      {/* Active voice session */}
      {isActive && (
        <div className="flex flex-col items-center gap-6">
          <VoiceOrb state={orbState} />

          <p className="text-sm text-gray-500 dark:text-gray-400">
            {isSpeaking ? "AI is speaking..." : "Listening..."}
          </p>

          {/* Show last AI message as a subtle caption */}
          {lastAiMessage && (
            <p className="text-center text-gray-600 dark:text-gray-300 text-sm max-w-sm leading-relaxed px-4">
              &ldquo;{lastAiMessage.length > 120 ? lastAiMessage.slice(0, 120) + "..." : lastAiMessage}&rdquo;
            </p>
          )}

          <button
            onClick={endSession}
            className="mt-4 bg-red-500/10 hover:bg-red-500/20 text-red-600 dark:text-red-400 font-medium py-2 px-6 rounded-full text-sm transition-colors"
          >
            End
          </button>
        </div>
      )}

      {/* Ended */}
      {status === "ended" && (
        <div className="flex flex-col items-center gap-4">
          <VoiceOrb state="idle" />
          <p className="text-gray-500">Session ended</p>
        </div>
      )}

      {error && (
        <p className="mt-4 text-red-600 text-sm text-center">{error}</p>
      )}
    </div>
  );
}

