"use client";

import { useState } from "react";
import { useVoiceSession } from "@/hooks/useVoiceSession";
import VoiceOrb from "@/components/VoiceOrb";

export default function CallInterface() {
  const [phoneNumber, setPhoneNumber] = useState("");

  const { status, error, callerInfo, isSpeaking, micAmplitude, startSession, endSession } =
    useVoiceSession({
      phoneNumber,
      mode: "call",
    });

  const isInCall = status === "connected" || status === "bypass";

  const handleStartCall = () => {
    if (!phoneNumber.trim()) return;
    startSession();
  };

  const orbState = !isInCall
    ? status === "connecting" ? "connecting" : "idle"
    : isSpeaking ? "speaking" : "listening";

  if (isInCall || status === "connecting") {
    return (
      <div className="flex flex-col items-center justify-center min-h-[80vh] px-4">
        <VoiceOrb state={orbState} amplitude={micAmplitude} />

        <p className="mt-6 text-sm text-gray-400 dark:text-gray-500">
          {status === "connecting"
            ? "Connecting..."
            : isSpeaking
              ? "Speaking..."
              : "Listening..."}
