"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import CallLogList from "@/components/dashboard/CallLogList";

export default function DashboardPage() {
  const [ownerName, setOwnerName] = useState<string | null>(null);

  useEffect(() => {
    fetch("/api/status")
      .then((r) => r.json())
      .then((data) => setOwnerName(data.owner_name))
      .catch(() => {});
  }, []);

  return (
    <main className="min-h-screen bg-gray-50 dark:bg-gray-950 text-gray-900 dark:text-gray-100">
      {/* Header */}
      <header className="bg-white dark:bg-gray-900 border-b border-gray-200 dark:border-gray-800 px-6 py-4">
        <div className="max-w-4xl mx-auto flex items-center justify-between">
          <div>
            <h1 className="text-xl font-bold">
              {ownerName ? `${ownerName}'s Dashboard` : "Call Dashboard"}
            </h1>
            <p className="text-sm text-gray-500">
              AI Receptionist — Call Logs
            </p>
          </div>
          <div className="flex gap-3">
            <Link
              href="/call"
              className="bg-green-600 hover:bg-green-700 text-white font-medium px-4 py-2 rounded-lg text-sm transition-colors"
            >
              Simulate Call
            </Link>
            <Link
              href="/"
              className="text-gray-500 hover:text-gray-700 dark:hover:text-gray-300 font-medium px-3 py-2 text-sm transition-colors"
            >
              Home
            </Link>
          </div>
        </div>
      </header>

      {/* Call Logs */}
      <div className="max-w-4xl mx-auto p-6">
        <CallLogList />
      </div>
    </main>
  );
}

