      {calls.length === 0 ? (
        <div className="text-center text-gray-500 py-12">
          <p className="text-lg mb-2">No calls yet</p>
          <p className="text-sm">
            Simulate a call to see it appear here in real time.
          </p>
        </div>
      ) : (
        calls.map((call) => (
          <CallLogCard
