"use client";

import { useState } from "react";
import { useVoiceSession } from "@/hooks/useVoiceSession";
import VoiceOrb from "@/components/VoiceOrb";

export default function CallInterface() {
  const [phoneNumber, setPhoneNumber] = useState("");

  const { status, error, callerInfo, isSpeaking, micAmplitude, startSession, endSession } =
    useVoiceSession({
      phoneNumber,
      mode: "call",
    });

  const isInCall = status === "connected" || status === "bypass";

  const handleStartCall = () => {
    if (!phoneNumber.trim()) return;
    startSession();
  };

  const orbState = !isInCall
    ? status === "connecting" ? "connecting" : "idle"
    : isSpeaking ? "speaking" : "listening";

  if (isInCall || status === "connecting") {
    return (
      <div className="flex flex-col items-center justify-center min-h-[80vh] px-4">
        <VoiceOrb state={orbState} amplitude={micAmplitude} />

        <p className="mt-6 text-sm text-gray-400 dark:text-gray-500">
          {status === "connecting"
            ? "Connecting..."
            : isSpeaking
              ? "Speaking..."
              : "Listening..."}
        </p>

        {callerInfo && (
          <div className="mt-4 flex items-center gap-2 text-xs">
            <span className={`px-2 py-1 rounded-full font-medium ${
              callerInfo.priority === "high"
                ? "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400"
                : callerInfo.priority === "medium"
                  ? "bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400"
                  : "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400"
            }`}>
              {callerInfo.caller_type}
            </span>
            {callerInfo.caller_name && (
              <span className="text-gray-500">{callerInfo.caller_name}</span>
            )}
            {callerInfo.is_scammer && (
              <span className="px-2 py-1 rounded-full bg-red-600 text-white font-bold">
                SCAMMER
              </span>
            )}
          </div>
        )}

        <p className="mt-4 text-xs text-gray-400 font-mono">{phoneNumber}</p>

        <button
          onClick={endSession}
          className="mt-6 w-14 h-14 bg-red-600 hover:bg-red-700 rounded-full flex items-center justify-center transition-colors active:scale-95 shadow-lg"
        >
          <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 24 24">
            <path d="M12 9c-1.6 0-3.15.25-4.6.72v3.1c0 .39-.23.74-.56.9-.98.49-1.87 1.12-2.66 1.85-.18.18-.43.28-.7.28-.28 0-.53-.11-.71-.29L.29 13.08a.956.956 0 01-.29-.7c0-.28.11-.53.29-.71C3.34 8.78 7.46 7 12 7s8.66 1.78 11.71 4.67c.18.18.29.43.29.71 0 .28-.11.53-.29.71l-2.48 2.48c-.18.18-.43.29-.71.29-.27 0-.52-.11-.7-.28a11.27 11.27 0 00-2.67-1.85.996.996 0 01-.56-.9v-3.1C15.15 9.25 13.6 9 12 9z" />
          </svg>
        </button>

        {error && <p className="mt-4 text-red-600 text-sm">{error}</p>}
      </div>
    );
  }

  return (
    <div className="flex flex-col items-center justify-center min-h-[80vh] px-4">
      <VoiceOrb state="idle" size="md" />

      <h1 className="mt-8 text-xl font-semibold text-gray-900 dark:text-white">
        Simulate a Call
      </h1>
      <p className="mt-2 text-sm text-gray-500 dark:text-gray-400 text-center max-w-xs">
        Enter a phone number to simulate an incoming call.
      </p>

      <div className="mt-8 w-full max-w-xs">
        <input
          type="tel"
          value={phoneNumber}
          onChange={(e) => setPhoneNumber(e.target.value)}
          placeholder="Phone number"
          className="w-full px-4 py-3 text-center text-lg border border-gray-200 dark:border-gray-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white dark:bg-gray-900 font-mono"
        />
      </div>

      <button
        onClick={handleStartCall}
        disabled={!phoneNumber.trim()}
        className="mt-6 bg-green-600 hover:bg-green-700 disabled:bg-gray-300 dark:disabled:bg-gray-700 text-white font-medium py-3 px-10 rounded-full text-base transition-all hover:shadow-lg active:scale-95 disabled:cursor-not-allowed"
      >
        Start Call
      </button>

      {status === "blocked" && (
        <p className="mt-4 text-red-600 text-sm">{error || "This number has been blocked."}</p>
      )}
      {status === "ended" && (
        <p className="mt-4 text-gray-500 text-sm">Call ended</p>
      )}
      {error && status === "error" && (
        <p className="mt-4 text-red-600 text-sm">{error}</p>
      )}
    </div>
  );
}

"use client";

import { useVoiceSession } from "@/hooks/useVoiceSession";
import { useCallback, useEffect, useRef, useState } from "react";
import VoiceOrb from "@/components/VoiceOrb";

interface Props {
  onComplete: () => void;
}

export default function PhaseScenario({ onComplete }: Props) {
  const [waitingToTransition, setWaitingToTransition] = useState(false);

  const handlePhaseComplete = useCallback(
    (phase: number) => {
      if (phase === 4) {
        setWaitingToTransition(true);
      }
    },
    []
  );

  const { status, error, isSpeaking, micAmplitude, startSession, endSession } =
    useVoiceSession({
      mode: "onboarding",
      onboardingPhase: 4,
      onPhaseComplete: handlePhaseComplete,
    });

  useEffect(() => {
    if (!waitingToTransition) return;
    if (isSpeaking) return;

    const timer = setTimeout(() => {
      onComplete();
    }, 800);
    return () => clearTimeout(timer);
  }, [waitingToTransition, isSpeaking, onComplete]);

  const isActive = status === "connected";

  const orbState = !isActive
    ? status === "connecting" ? "connecting" : "idle"
    : isSpeaking ? "speaking" : "listening";

  return (
    <div className="flex flex-col items-center min-h-[60vh] justify-center">
      {status === "idle" && (
        <div className="flex flex-col items-center gap-6">
          <VoiceOrb state="idle" />
          <div className="text-center">
            <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
              Quick scenario test
            </h2>
            <p className="text-gray-500 dark:text-gray-400 text-sm max-w-xs">
              The AI will roleplay a few caller scenarios to show you how it handles them.
            </p>
          </div>
          <div className="flex flex-col items-center gap-3 mt-2">
            <button
              onClick={startSession}
              className="bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-10 rounded-full text-base transition-all hover:shadow-lg active:scale-95"
            >
              Start Test
            </button>
            <button
              onClick={onComplete}
              className="text-sm text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 transition-colors"
            >
              Skip this step
            </button>
          </div>
        </div>
      )}

      {status === "connecting" && (
        <div className="flex flex-col items-center gap-6">
          <VoiceOrb state="connecting" />
          <p className="text-amber-600 dark:text-amber-400 font-medium text-sm">Connecting...</p>
        </div>
      )}

      {isActive && (
        <div className="flex flex-col items-center gap-4">
          <VoiceOrb state={orbState} amplitude={micAmplitude} />
          <p className="text-sm text-gray-400 dark:text-gray-500">
            {isSpeaking ? "Speaking..." : "Listening..."}
          </p>
          <button
            onClick={endSession}
            className="mt-4 bg-red-500/10 hover:bg-red-500/20 text-red-600 dark:text-red-400 font-medium py-2 px-6 rounded-full text-sm transition-colors"
          >
            End
          </button>
        </div>
      )}

      {status === "ended" && (
        <div className="flex flex-col items-center gap-4">
          <VoiceOrb state="idle" />
          <p className="text-gray-500 text-sm">Session ended</p>
        </div>
      )}

      {error && <p className="mt-4 text-red-600 text-sm text-center">{error}</p>}
    </div>
  );
}

"use client";

import { useVoiceSession } from "@/hooks/useVoiceSession";
import { useCallback, useEffect, useRef, useState } from "react";
import VoiceOrb from "@/components/VoiceOrb";

interface Props {
  onComplete: (data: Record<string, unknown>) => void;
}

export default function PhasePreferences({ onComplete }: Props) {
  const pendingRef = useRef<Record<string, unknown> | null>(null);
  const [waitingToTransition, setWaitingToTransition] = useState(false);

  const handlePhaseComplete = useCallback(
    (phase: number, data?: Record<string, unknown>) => {
      if (phase === 3 && data) {
        pendingRef.current = data;
        setWaitingToTransition(true);
      }
    },
    []
  );

  const { status, error, isSpeaking, micAmplitude, startSession, endSession } =
    useVoiceSession({
      mode: "onboarding",
      onboardingPhase: 3,
      onPhaseComplete: handlePhaseComplete,
    });

  useEffect(() => {
    if (!waitingToTransition || !pendingRef.current) return;
    if (isSpeaking) return;

    const timer = setTimeout(() => {
      if (pendingRef.current) {
        onComplete(pendingRef.current);
      }
    }, 800);
    return () => clearTimeout(timer);
  }, [waitingToTransition, isSpeaking, onComplete]);

  const isActive = status === "connected";

  const orbState = !isActive
    ? status === "connecting" ? "connecting" : "idle"
    : isSpeaking ? "speaking" : "listening";

  return (
    <div className="flex flex-col items-center min-h-[60vh] justify-center">
      {status === "idle" && (
        <div className="flex flex-col items-center gap-6">
          <VoiceOrb state="idle" />
          <div className="text-center">
            <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
              Set your preferences
            </h2>
            <p className="text-gray-500 dark:text-gray-400 text-sm max-w-xs">
              Tell the AI how to handle deliveries, sales calls, and any custom rules.
            </p>
          </div>
          <button
            onClick={startSession}
            className="mt-2 bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-10 rounded-full text-base transition-all hover:shadow-lg active:scale-95"
          >
            Start
          </button>
        </div>
      )}

      {status === "connecting" && (
        <div className="flex flex-col items-center gap-6">
          <VoiceOrb state="connecting" />
          <p className="text-amber-600 dark:text-amber-400 font-medium text-sm">Connecting...</p>
        </div>
      )}

      {isActive && (
        <div className="flex flex-col items-center gap-4">
          <VoiceOrb state={orbState} amplitude={micAmplitude} />
          <p className="text-sm text-gray-400 dark:text-gray-500">
            {isSpeaking ? "Speaking..." : "Listening..."}
          </p>
          <button
            onClick={endSession}
            className="mt-4 bg-red-500/10 hover:bg-red-500/20 text-red-600 dark:text-red-400 font-medium py-2 px-6 rounded-full text-sm transition-colors"
          >
            End
          </button>
        </div>
      )}

      {status === "ended" && (
        <div className="flex flex-col items-center gap-4">
          <VoiceOrb state="idle" />
          <p className="text-gray-500 text-sm">Session ended</p>
        </div>
      )}

      {error && <p className="mt-4 text-red-600 text-sm text-center">{error}</p>}
    </div>
  );
}

