import PhaseBasics from "@/components/onboarding/PhaseBasics";
import PhaseContacts from "@/components/onboarding/PhaseContacts";
import PhasePreferences from "@/components/onboarding/PhasePreferences";
import PhaseScenario from "@/components/onboarding/PhaseScenario";
import PhaseConfirm from "@/components/onboarding/PhaseConfirm";

interface OnboardingData {
  name: string;
  language: string;
  contacts: { name: string; relationship: string; phone_number: string; priority: string }[];
  deliveryInstructions: string;
  callPreferences: Record<string, string>;
  customRules: string[];
}

export default function OnboardingPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [phase, setPhase] = useState(1);
  const [data, setData] = useState<OnboardingData>({
    name: "",
    language: "english",
    contacts: [],
    deliveryInstructions: "",
    callPreferences: {},
    customRules: [],
  });

  useEffect(() => {
    fetch("/api/status")
      .then((r) => r.json())
      .then((d) => {
        if (d.onboarding_complete) router.replace("/dashboard");
        else setLoading(false);
      })
      .catch(() => setLoading(false));
  }, [router]);

  const handleBasicsComplete = useCallback(
    (basics: { name: string; language: string }) => {
      setData((prev) => ({ ...prev, name: basics.name, language: basics.language }));
      setPhase(2);
    },
    []
  );

  const handleContactsComplete = useCallback(
    async (
      contacts: { name: string; relationship: string; phone_number: string; priority: string }[]
    ) => {
      // Save contacts to backend
      for (const contact of contacts) {
        await fetch("/api/contacts", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(contact),
        });
      }
      setData((prev) => ({ ...prev, contacts }));
      setPhase(3);
    },
    []
  );

  const handlePreferencesComplete = useCallback(
    (prefs: Record<string, unknown>) => {
      setData((prev) => ({
        ...prev,
        deliveryInstructions: (prefs.delivery_instructions as string) || "",
        callPreferences: (prefs.call_preferences as Record<string, string>) || {},
        customRules: (prefs.custom_rules as string[]) || [],
      }));
      setPhase(4);
    },
    []
  );

  const handleScenarioComplete = useCallback(() => {
    setPhase(5);
  }, []);

  const handleConfirm = useCallback(async () => {
    await fetch("/api/onboarding", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: data.name,
        default_language: data.language,
        delivery_instructions: data.deliveryInstructions,
        call_preferences: data.callPreferences,
        custom_rules: data.customRules,
      }),
    });
    router.push("/dashboard");
  }, [data, router]);

  if (loading) {
    return (
      <main className="min-h-screen flex items-center justify-center bg-white dark:bg-gray-950">
        <div className="text-gray-500">Loading...</div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-white dark:bg-gray-950 text-gray-900 dark:text-gray-100 py-8 px-4">
      <div className="max-w-2xl mx-auto">
        <PhaseStepper current={phase} />

        {phase === 1 && <PhaseBasics onComplete={handleBasicsComplete} />}

        {phase === 2 && <PhaseContacts onComplete={handleContactsComplete} />}

        {phase === 3 && (
          <PhasePreferences onComplete={handlePreferencesComplete} />
        )}

        {phase === 4 && <PhaseScenario onComplete={handleScenarioComplete} />}

        {phase === 5 && (
          <PhaseConfirm
            ownerName={data.name}
            language={data.language}
            contactCount={data.contacts.length}
            deliveryInstructions={data.deliveryInstructions}
            callPreferences={data.callPreferences}
            onConfirm={handleConfirm}
          />
        )}
      </div>
    </main>
  );
}

