13	export default function CallLogCard({ call, onFlagSpam, onVerifyType, onAddContact }: Props) {
14	  const [showHistory, setShowHistory] = useState(false);
15	  const [verifyInput, setVerifyInput] = useState("");
16	  const [showVerify, setShowVerify] = useState(false);
17	  const [showAddContact, setShowAddContact] = useState(false);
18	  const [contactForm, setContactForm] = useState({ name: "", relationship: "", priority: "medium" });
19	
20	  const borderColor =
21	    call.priority === "high"
22	      ? "border-l-red-500"
23	      : call.priority === "medium"
24	        ? "border-l-yellow-500"
25	        : "border-l-gray-300";
26	
27	  const priorityBadge =
28	    call.priority === "high"
29	      ? "bg-red-100 text-red-700"
30	      : call.priority === "medium"
31	        ? "bg-yellow-100 text-yellow-700"
32	        : "bg-gray-100 text-gray-600";
33	
34	  const timeAgo = getTimeAgo(call.timestamp);
35	
36	  return (
37	    <div className={`border-l-4 ${borderColor} bg-white dark:bg-gray-900 rounded-lg shadow-sm p-4 mb-3`}>
38	      {/* Header row */}
39	      <div className="flex items-center justify-between mb-2">
40	        <div className="flex items-center gap-3">
41	          <span className="font-mono text-sm">{call.phone_number}</span>
42	          <span className={`px-2 py-0.5 rounded text-xs font-medium ${priorityBadge}`}>
43	            {call.priority}
44	          </span>
45	          <span className="px-2 py-0.5 rounded text-xs font-medium bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300">
46	            {call.owner_verified_type || call.type || "screening"}
47	          </span>
48	        </div>
49	        <span className="text-xs text-gray-500">{timeAgo}</span>
50	      </div>
51	
52	      {/* Details */}
53	      <div className="text-sm text-gray-700 dark:text-gray-300 mb-2">
54	        {call.caller_name && (
55	          <span className="font-medium">{call.caller_name} — </span>
56	        )}
57	        {call.message || "No message recorded"}
58	      </div>
59	
60	      {/* Meta */}
61	      <div className="flex items-center gap-4 text-xs text-gray-500 mb-3">
62	        <span>Action: {call.action_taken}</span>
63	        {call.language_states.length > 0 && (
64	          <span>Languages: {call.language_states.join(" → ")}</span>
65	        )}
66	      </div>
67	
68	      {/* Actions */}
69	      <div className="flex flex-wrap gap-2">
70	        <button
71	          onClick={() => setShowAddContact(!showAddContact)}
72	          className="text-xs px-3 py-1 bg-blue-50 hover:bg-blue-100 text-blue-700 rounded dark:bg-blue-900/30 dark:text-blue-400"
73	        >
74	          Add to Contacts
75	        </button>
76	        <button
77	          onClick={() => onFlagSpam(call.phone_number)}
78	          className="text-xs px-3 py-1 bg-red-50 hover:bg-red-100 text-red-700 rounded dark:bg-red-900/30 dark:text-red-400"
79	        >
80	          Mark as Spam
81	        </button>
82	        <button
83	          onClick={() => setShowVerify(!showVerify)}
84	          className="text-xs px-3 py-1 bg-gray-50 hover:bg-gray-100 text-gray-700 rounded dark:bg-gray-800 dark:text-gray-400"
85	        >
86	          Verify Type
87	        </button>
88	        {call.conversation_history.length > 0 && (
89	          <button
90	            onClick={() => setShowHistory(!showHistory)}
91	            className="text-xs px-3 py-1 bg-gray-50 hover:bg-gray-100 text-gray-700 rounded dark:bg-gray-800 dark:text-gray-400"
92	          >
93	            {showHistory ? "Hide" : "Show"} Transcript
94	          </button>
95	        )}
96	      </div>
97	
98	      {/* Verify Type Input */}
99	      {showVerify && (
100	        <div className="mt-3 flex gap-2">
101	          <input
102	            type="text"
103	            value={verifyInput}
104	            onChange={(e) => setVerifyInput(e.target.value)}
105	            placeholder="Correct type (e.g., recruiter)"
106	            className="flex-1 text-sm px-3 py-1 border rounded dark:bg-gray-800 dark:border-gray-600"
107	          />
108	          <button
109	            onClick={() => {
110	              if (verifyInput.trim()) {
111	                onVerifyType(call.call_id, verifyInput.trim());
112	                setShowVerify(false);
113	                setVerifyInput("");
114	              }
115	            }}
116	            className="text-sm px-3 py-1 bg-blue-600 text-white rounded hover:bg-blue-700"
117	          >
118	            Save
119	          </button>
120	        </div>
121	      )}
122	
123	      {/* Add Contact Form */}
124	      {showAddContact && (
125	        <div className="mt-3 space-y-2">
126	          <input
127	            type="text"
128	            value={contactForm.name}
129	            onChange={(e) => setContactForm({ ...contactForm, name: e.target.value })}
130	            placeholder="Name"
131	            className="w-full text-sm px-3 py-1 border rounded dark:bg-gray-800 dark:border-gray-600"
132	          />
133	          <input
134	            type="text"
135	            value={contactForm.relationship}
136	            onChange={(e) => setContactForm({ ...contactForm, relationship: e.target.value })}
137	            placeholder="Relationship (friend, family, etc.)"
138	            className="w-full text-sm px-3 py-1 border rounded dark:bg-gray-800 dark:border-gray-600"
139	          />
140	          <div className="flex gap-2">
141	            <select
142	              value={contactForm.priority}
143	              onChange={(e) => setContactForm({ ...contactForm, priority: e.target.value })}
144	              className="text-sm px-3 py-1 border rounded dark:bg-gray-800 dark:border-gray-600"
145	            >
146	              <option value="high">High</option>
147	              <option value="medium">Medium</option>
148	              <option value="low">Low</option>
149	            </select>
150	            <button
151	              onClick={() => {
152	                if (contactForm.name.trim()) {
153	                  onAddContact(call.call_id, contactForm.name, contactForm.relationship, contactForm.priority);
154	                  setShowAddContact(false);
155	                  setContactForm({ name: "", relationship: "", priority: "medium" });
156	                }
157	              }}
158	              className="text-sm px-3 py-1 bg-blue-600 text-white rounded hover:bg-blue-700"
159	            >
160	              Save Contact
161	            </button>
162	          </div>
163	        </div>
164	      )}
165	
166	      {/* Conversation History */}
167	      {showHistory && (
168	        <div className="mt-3 border-t pt-3 space-y-2 max-h-60 overflow-y-auto">
169	          {call.conversation_history.map((turn, i) => (
170	            <div key={i} className={`text-sm ${turn.role === "caller" ? "text-blue-700 dark:text-blue-400" : "text-gray-600 dark:text-gray-400"}`}>
171	              <span className="font-medium">{turn.role === "caller" ? "Caller" : "AI"}:</span> {turn.text}
172	            </div>
173	          ))}
174	        </div>
175	      )}
176	    </div>
177	  );
178	}
179	
180	function getTimeAgo(timestamp: number): string {
181	  const seconds = Math.floor(Date.now() / 1000 - timestamp);
182	  if (seconds < 60) return "just now";
183	  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`;
184	  if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`;
185	  return new Date(timestamp * 1000).toLocaleDateString();
186	}
