1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState } from "react";
4	import { getWsBaseUrl } from "./wsUrl";
5	
6	interface CallLog {
7	  call_id: number;
8	  phone_number: string;
9	  caller_name: string | null;
10	  message: string;
11	  conversation_history: { role: string; text: string; timestamp: number }[];
12	  type: string;
13	  priority: "high" | "medium" | "low";
14	  language_states: string[];
15	  timestamp: number;
16	  action_taken: string;
17	  owner_verified_type: string | null;
18	}
19	
20	const PRIORITY_ORDER: Record<string, number> = {
21	  high: 0,
22	  medium: 1,
23	  low: 2,
24	};
25	
26	function sortByPriority(calls: CallLog[]): CallLog[] {
27	  return [...calls].sort(
28	    (a, b) =>
29	      (PRIORITY_ORDER[a.priority] ?? 3) - (PRIORITY_ORDER[b.priority] ?? 3) ||
30	      b.timestamp - a.timestamp
31	  );
32	}
33	
34	export type { CallLog };
35	
36	export function useDashboardWS() {
37	  const [calls, setCalls] = useState<CallLog[]>([]);
38	  const [connected, setConnected] = useState(false);
39	  const wsRef = useRef<WebSocket | null>(null);
40	  const reconnectTimeoutRef = useRef<NodeJS.Timeout | null>(null);
41	
42	  const connect = useCallback(() => {
43	    const ws = new WebSocket(`${getWsBaseUrl()}/ws/dashboard`);
44	    wsRef.current = ws;
45	
46	    ws.onopen = () => setConnected(true);
47	
48	    ws.onmessage = (event) => {
49	      const msg = JSON.parse(event.data);
50	
51	      if (msg.type === "full_sync") {
52	        setCalls(sortByPriority(msg.calls || []));
53	      } else if (msg.type === "new_call") {
54	        setCalls((prev) => sortByPriority([msg.call, ...prev]));
55	      } else if (msg.type === "call_updated") {
56	        setCalls((prev) =>
57	          sortByPriority(
58	            prev.map((c) => (c.call_id === msg.call.call_id ? msg.call : c))
59	          )
60	        );
61	      }
62	    };
63	
64	    ws.onclose = () => {
65	      setConnected(false);
66	      reconnectTimeoutRef.current = setTimeout(connect, 3000);
67	    };
68	
69	    ws.onerror = () => ws.close();
70	  }, []);
71	
72	  useEffect(() => {
73	    connect();
74	    return () => {
75	      if (reconnectTimeoutRef.current) clearTimeout(reconnectTimeoutRef.current);
76	      wsRef.current?.close();
77	    };
78	  }, [connect]);
79	
80	  const sendAction = useCallback(
81	    (action: Record<string, unknown>) => {
82	      if (wsRef.current?.readyState === WebSocket.OPEN) {
83	        wsRef.current.send(JSON.stringify(action));
84	      }
85	    },
86	    []
87	  );
88	
89	  return { calls, connected, sendAction };
90	}
