"use client";

import { useState } from "react";
import type { CallLog } from "@/hooks/useDashboardWS";

interface Props {
  call: CallLog;
  onFlagSpam: (phoneNumber: string) => void;
  onVerifyType: (callId: number, type: string) => void;
  onAddContact: (callId: number, name: string, relationship: string, priority: string) => void;
}

export default function CallLogCard({ call, onFlagSpam, onVerifyType, onAddContact }: Props) {
  const [showHistory, setShowHistory] = useState(false);
  const [verifyInput, setVerifyInput] = useState("");
  const [showVerify, setShowVerify] = useState(false);
  const [showAddContact, setShowAddContact] = useState(false);
  const [contactForm, setContactForm] = useState({ name: "", relationship: "", priority: "medium" });

  const borderColor =
    call.priority === "high"
      ? "border-l-red-500"
      : call.priority === "medium"
        ? "border-l-yellow-500"
        : "border-l-gray-300";

  const priorityBadge =
    call.priority === "high"
      ? "bg-red-100 text-red-700"
      : call.priority === "medium"
        ? "bg-yellow-100 text-yellow-700"
        : "bg-gray-100 text-gray-600";

  const timeAgo = getTimeAgo(call.timestamp);

  return (
    <div className={`border-l-4 ${borderColor} bg-white dark:bg-gray-900 rounded-lg shadow-sm p-4 mb-3`}>
      {/* Header row */}
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-3">
          <span className="font-mono text-sm">{call.phone_number}</span>
          <span className={`px-2 py-0.5 rounded text-xs font-medium ${priorityBadge}`}>
            {call.priority}
          </span>
          <span className="px-2 py-0.5 rounded text-xs font-medium bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300">
            {call.owner_verified_type || call.type || "screening"}
          </span>
        </div>
        <span className="text-xs text-gray-500">{timeAgo}</span>
      </div>

      {/* Details */}
      <div className="text-sm text-gray-700 dark:text-gray-300 mb-2">
        {call.caller_name && (
          <span className="font-medium">{call.caller_name} — </span>
        )}
        {call.message || "No message recorded"}
      </div>

      {/* Meta */}
      <div className="flex items-center gap-4 text-xs text-gray-500 mb-3">
        <span>Action: {call.action_taken}</span>
        {call.language_states.length > 0 && (
          <span>Languages: {call.language_states.join(" → ")}</span>
        )}
      </div>

      {/* Actions */}
      <div className="flex flex-wrap gap-2">
        <button
          onClick={() => setShowAddContact(!showAddContact)}
          className="text-xs px-3 py-1 bg-blue-50 hover:bg-blue-100 text-blue-700 rounded dark:bg-blue-900/30 dark:text-blue-400"
        >
          Add to Contacts
        </button>
        <button
          onClick={() => onFlagSpam(call.phone_number)}
          className="text-xs px-3 py-1 bg-red-50 hover:bg-red-100 text-red-700 rounded dark:bg-red-900/30 dark:text-red-400"
        >
          Mark as Spam
        </button>
        <button
          onClick={() => setShowVerify(!showVerify)}
          className="text-xs px-3 py-1 bg-gray-50 hover:bg-gray-100 text-gray-700 rounded dark:bg-gray-800 dark:text-gray-400"
        >
          Verify Type
        </button>
        {call.conversation_history.length > 0 && (
          <button
            onClick={() => setShowHistory(!showHistory)}
            className="text-xs px-3 py-1 bg-gray-50 hover:bg-gray-100 text-gray-700 rounded dark:bg-gray-800 dark:text-gray-400"
          >
            {showHistory ? "Hide" : "Show"} Transcript
          </button>
        )}
      </div>

      {/* Verify Type Input */}
      {showVerify && (
        <div className="mt-3 flex gap-2">
          <input
            type="text"
            value={verifyInput}
            onChange={(e) => setVerifyInput(e.target.value)}
            placeholder="Correct type (e.g., recruiter)"
            className="flex-1 text-sm px-3 py-1 border rounded dark:bg-gray-800 dark:border-gray-600"
          />
          <button
            onClick={() => {
              if (verifyInput.trim()) {
                onVerifyType(call.call_id, verifyInput.trim());
                setShowVerify(false);
                setVerifyInput("");
              }
            }}
            className="text-sm px-3 py-1 bg-blue-600 text-white rounded hover:bg-blue-700"
          >
            Save
          </button>
        </div>
      )}

      {/* Add Contact Form */}
      {showAddContact && (
        <div className="mt-3 space-y-2">
          <input
            type="text"
            value={contactForm.name}
            onChange={(e) => setContactForm({ ...contactForm, name: e.target.value })}
            placeholder="Name"
            className="w-full text-sm px-3 py-1 border rounded dark:bg-gray-800 dark:border-gray-600"
          />
          <input
            type="text"
            value={contactForm.relationship}
            onChange={(e) => setContactForm({ ...contactForm, relationship: e.target.value })}
            placeholder="Relationship (friend, family, etc.)"
            className="w-full text-sm px-3 py-1 border rounded dark:bg-gray-800 dark:border-gray-600"
          />
          <div className="flex gap-2">
            <select
              value={contactForm.priority}
              onChange={(e) => setContactForm({ ...contactForm, priority: e.target.value })}
              className="text-sm px-3 py-1 border rounded dark:bg-gray-800 dark:border-gray-600"
            >
              <option value="high">High</option>
              <option value="medium">Medium</option>
              <option value="low">Low</option>
            </select>
            <button
              onClick={() => {
                if (contactForm.name.trim()) {
                  onAddContact(call.call_id, contactForm.name, contactForm.relationship, contactForm.priority);
                  setShowAddContact(false);
                  setContactForm({ name: "", relationship: "", priority: "medium" });
                }
              }}
              className="text-sm px-3 py-1 bg-blue-600 text-white rounded hover:bg-blue-700"
            >
              Save Contact
            </button>
          </div>
        </div>
      )}

      {/* Conversation History */}
      {showHistory && (
        <div className="mt-3 border-t pt-3 space-y-2 max-h-60 overflow-y-auto">
          {call.conversation_history.map((turn, i) => (
            <div key={i} className={`text-sm ${turn.role === "caller" ? "text-blue-700 dark:text-blue-400" : "text-gray-600 dark:text-gray-400"}`}>
              <span className="font-medium">{turn.role === "caller" ? "Caller" : "AI"}:</span> {turn.text}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

function getTimeAgo(timestamp: number): string {
  const seconds = Math.floor(Date.now() / 1000 - timestamp);
  if (seconds < 60) return "just now";
  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`;
  if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`;
  return new Date(timestamp * 1000).toLocaleDateString();
}

