"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { getWsBaseUrl } from "./wsUrl";

export interface TranscriptEntry {
  role: "caller" | "ai";
  text: string;
}

export interface CallerInfo {
  caller_type: string;
  caller_name: string | null;
  priority: string;
  language: string;
  is_scammer: boolean;
}

interface VoiceSessionOptions {
  phoneNumber?: string;
  mode?: "call" | "onboarding";
  onboardingPhase?: number;
  onPhaseComplete?: (phase: number, data?: Record<string, unknown>) => void;
}

type SessionStatus =
  | "idle"
  | "connecting"
  | "connected"
  | "blocked"
  | "bypass"
  | "ended"
  | "error";

export function useVoiceSession(options: VoiceSessionOptions = {}) {
  const {
    phoneNumber = "",
    mode = "call",
    onboardingPhase = 0,
    onPhaseComplete,
  } = options;

  const [status, setStatus] = useState<SessionStatus>("idle");
  const [error, setError] = useState<string | null>(null);
  const [transcript, setTranscript] = useState<TranscriptEntry[]>([]);
  const [callerInfo, setCallerInfo] = useState<CallerInfo | null>(null);
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [micAmplitude, setMicAmplitude] = useState(0);

  const wsRef = useRef<WebSocket | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const workletNodeRef = useRef<AudioWorkletNode | null>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const playbackTimeRef = useRef<number>(0);
  const scheduledSourcesRef = useRef<AudioBufferSourceNode[]>([]);
  const isActiveRef = useRef(false);

  const cancelQueuedAudio = useCallback(() => {
    for (const src of scheduledSourcesRef.current) {
      try { src.stop(); } catch { /* already stopped */ }
    }
    scheduledSourcesRef.current = [];
    playbackTimeRef.current = 0;
    setIsSpeaking(false);
  }, []);

  const cleanup = useCallback(() => {
    isActiveRef.current = false;
    cancelQueuedAudio();

    if (workletNodeRef.current) {
      workletNodeRef.current.disconnect();
      workletNodeRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((t) => t.stop());
      streamRef.current = null;
    }
    if (audioContextRef.current) {
      audioContextRef.current.close().catch(() => {});
      audioContextRef.current = null;
    }
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
  }, [cancelQueuedAudio]);

  useEffect(() => {
    return () => cleanup();
  }, [cleanup]);

  const startSession = useCallback(async () => {
    cleanup();
    setStatus("connecting");
    setError(null);
    setTranscript([]);
    setCallerInfo(null);
    setIsSpeaking(false);
    setMicAmplitude(0);
    isActiveRef.current = true;

    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        audio: {
          sampleRate: 24000,
          channelCount: 1,
          echoCancellation: true,
          noiseSuppression: true,
        },
      });
      streamRef.current = stream;

      const audioContext = new AudioContext({ sampleRate: 24000 });
      audioContextRef.current = audioContext;

      await audioContext.audioWorklet.addModule("/audio-processor.js");
      const source = audioContext.createMediaStreamSource(stream);
      const workletNode = new AudioWorkletNode(
        audioContext,
        "audio-capture-processor"
      );
      workletNodeRef.current = workletNode;

      const wsUrl = `${getWsBaseUrl()}/ws/voice`;
      const ws = new WebSocket(wsUrl);
      wsRef.current = ws;

      ws.onopen = () => {
        ws.send(
          JSON.stringify({
            type: mode === "onboarding" ? "start_onboarding" : "start_call",
            phone_number: phoneNumber,
            phase: onboardingPhase,
          })
        );
      };

      workletNode.port.onmessage = (event) => {
        const { data, amplitude } = event.data;

        if (amplitude !== undefined) {
          setMicAmplitude(Math.min(1, amplitude * 4));
        }

        if (
          !isActiveRef.current ||
          !ws ||
          ws.readyState !== WebSocket.OPEN
        )
          return;

        const bytes = new Uint8Array(data);
        let binary = "";
        for (let i = 0; i < bytes.byteLength; i++) {
          binary += String.fromCharCode(bytes[i]);
        }
        const base64 = btoa(binary);
        ws.send(JSON.stringify({ type: "audio_data", audio: base64 }));
      };

      source.connect(workletNode);
      workletNode.connect(audioContext.destination);

      ws.onmessage = (event) => {
        const msg = JSON.parse(event.data);

        switch (msg.type) {
          case "status":
            if (msg.status === "connected") {
              setStatus("connected");
            } else if (msg.status === "bypass") {
              setStatus("bypass");
            }
            break;

          case "blocked":
            setStatus("blocked");
            setError(msg.reason || "This number has been blocked.");
            cleanup();
            break;

          case "audio_data":
            setIsSpeaking(true);
            playAudioQueued(msg.audio, audioContext, playbackTimeRef, scheduledSourcesRef);
            break;

          case "audio_done":
            setIsSpeaking(false);
            break;

          case "speech_started":
            cancelQueuedAudio();
            break;

          case "transcript":
            setTranscript((prev) => [
              ...prev,
              { role: msg.role, text: msg.text },
            ]);
            break;

          case "caller_info":
            setCallerInfo(msg);
            break;

          case "onboarding_phase_complete":
            onPhaseComplete?.(msg.phase, msg.data);
            break;

          case "error":
            setError(msg.message);
            setStatus("error");
            break;
        }
      };

      ws.onclose = () => {
        if (isActiveRef.current) {
          setStatus("ended");
        }
      };

      ws.onerror = () => {
        setError("WebSocket connection failed");
        setStatus("error");
      };
    } catch (err) {
      const message =
        err instanceof Error ? err.message : "Failed to start voice session";
      setError(message);
      setStatus("error");
      cleanup();
    }
  }, [phoneNumber, mode, onboardingPhase, onPhaseComplete, cleanup, cancelQueuedAudio]);

  const endSession = useCallback(() => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({ type: "end_call" }));
    }
    setStatus("ended");
    cleanup();
  }, [cleanup]);

  return {
    status,
    error,
    transcript,
    callerInfo,
    isSpeaking,
    micAmplitude,
    startSession,
    endSession,
  };
}

function playAudioQueued(
  base64Audio: string,
  audioContext: AudioContext,
  playbackTimeRef: React.MutableRefObject<number>,
  scheduledSourcesRef: React.MutableRefObject<AudioBufferSourceNode[]>
) {
  const binary = atob(base64Audio);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }

  const int16 = new Int16Array(bytes.buffer);
  const float32 = new Float32Array(int16.length);
  for (let i = 0; i < int16.length; i++) {
    float32[i] = int16[i] / 32768;
  }

  const audioBuffer = audioContext.createBuffer(1, float32.length, 24000);
  audioBuffer.getChannelData(0).set(float32);

  const source = audioContext.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(audioContext.destination);

  const startTime = Math.max(audioContext.currentTime + 0.01, playbackTimeRef.current);
  source.start(startTime);
  playbackTimeRef.current = startTime + audioBuffer.duration;

  scheduledSourcesRef.current.push(source);
  source.onended = () => {
    scheduledSourcesRef.current = scheduledSourcesRef.current.filter((s) => s !== source);
  };
}

"use client";

import { useState, useCallback, useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import PhaseStepper from "@/components/onboarding/PhaseStepper";
import PhaseContacts from "@/components/onboarding/PhaseContacts";
import PhaseConfirm from "@/components/onboarding/PhaseConfirm";
import VoiceOrb from "@/components/VoiceOrb";
import { useVoiceSession } from "@/hooks/useVoiceSession";

type UIPhase = "voice" | "contacts" | "confirm";

interface OnboardingData {
  name: string;
  language: string;
  contacts: { name: string; relationship: string; phone_number: string; priority: string }[];
  deliveryInstructions: string;
  callPreferences: Record<string, string>;
  customRules: string[];
}

export default function OnboardingPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [uiPhase, setUIPhase] = useState<UIPhase>("voice");
  const [step, setStep] = useState(1);
  const [data, setData] = useState<OnboardingData>({
    name: "",
    language: "english",
    contacts: [],
    deliveryInstructions: "",
    callPreferences: {},
    customRules: [],
  });
  const sessionStartedRef = useRef(false);

  useEffect(() => {
    fetch("/api/status")
      .then((r) => r.json())
      .then((d) => {
        if (d.onboarding_complete) router.replace("/dashboard");
        else setLoading(false);
      })
      .catch(() => setLoading(false));
  }, [router]);

  const handlePhaseComplete = useCallback(
    (phase: string, phaseData?: Record<string, unknown>) => {
      switch (phase) {
        case "basics_saved":
          if (phaseData) {
            setData((prev) => ({
              ...prev,
              name: (phaseData.name as string) || prev.name,
              language: (phaseData.language as string) || prev.language,
            }));
          }
          setStep(2);
          break;

        case "show_contacts":
          setUIPhase("contacts");
          setStep(2);
          break;

        case "contact_added":
          if (phaseData) {
            setData((prev) => ({
              ...prev,
              contacts: [
                ...prev.contacts,
                {
                  name: (phaseData.name as string) || "",
                  phone_number: (phaseData.phone_number as string) || "",
                  relationship: (phaseData.relationship as string) || "",
                  priority: (phaseData.priority as string) || "medium",
                },
              ],
            }));
          }
          break;

        case "contacts_done":
          setUIPhase("voice");
          setStep(3);
          break;

        case "preferences_saved":
          if (phaseData) {
            setData((prev) => ({
              ...prev,
              deliveryInstructions: (phaseData.delivery_instructions as string) || "",
              callPreferences: (phaseData.call_preferences as Record<string, string>) || {},
              customRules: (phaseData.custom_rules as string[]) || [],
            }));
          }
          setStep(4);
          break;

        case "scenario_complete":
          setUIPhase("confirm");
          setStep(5);
          break;
      }
    },
    []
  );

  const { status, error, isSpeaking, micAmplitude, startSession, endSession } =
    useVoiceSession({
      mode: "onboarding",
      onboardingPhase: 0,
      onPhaseComplete: handlePhaseComplete,
    });

  // Auto-start the voice session once loaded
  useEffect(() => {
    if (!loading && !sessionStartedRef.current && status === "idle") {
      sessionStartedRef.current = true;
      startSession();
    }
  }, [loading, status, startSession]);

  const handleContactsComplete = useCallback(
    async (
      contacts: { name: string; relationship: string; phone_number: string; priority: string }[]
    ) => {
      for (const contact of contacts) {
        await fetch("/api/contacts", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(contact),
        });
      }
      setData((prev) => ({
        ...prev,
        contacts: [...prev.contacts, ...contacts],
      }));
      setUIPhase("voice");
      setStep(3);
    },
    []
  );

  const handleConfirm = useCallback(async () => {
    await fetch("/api/onboarding", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: data.name,
        default_language: data.language,
        delivery_instructions: data.deliveryInstructions,
        call_preferences: data.callPreferences,
        custom_rules: data.customRules,
      }),
    });
    router.push("/dashboard");
  }, [data, router]);

  if (loading) {
    return (
      <main className="min-h-screen flex items-center justify-center bg-white dark:bg-gray-950">
        <div className="text-gray-500">Loading...</div>
      </main>
    );
  }

  const isActive = status === "connected";
  const orbState =
    !isActive
      ? status === "connecting"
        ? "connecting"
        : "idle"
      : isSpeaking
        ? "speaking"
        : "listening";

  return (
    <main className="min-h-screen bg-white dark:bg-gray-950 text-gray-900 dark:text-gray-100">
      <div className="max-w-2xl mx-auto py-8 px-4">
        <PhaseStepper current={step} />

        {/* Voice phase — full-screen orb */}
        {uiPhase === "voice" && (
          <div className="flex flex-col items-center justify-center min-h-[65vh]">
            {status === "idle" && !sessionStartedRef.current && (
              <div className="flex flex-col items-center gap-6">
                <VoiceOrb state="idle" />
                <div className="text-center">
                  <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
                    Let&apos;s set up your AI Receptionist
                  </h2>
                  <p className="text-gray-500 dark:text-gray-400 text-sm max-w-xs">
                    We&apos;ll have a quick conversation to get everything configured.
                  </p>
                </div>
                <button
                  onClick={startSession}
                  className="mt-2 bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-10 rounded-full text-base transition-all hover:shadow-lg active:scale-95"
                >
                  Start
                </button>
              </div>
            )}

            {status === "connecting" && (
              <div className="flex flex-col items-center gap-6">
                <VoiceOrb state="connecting" />
                <p className="text-amber-600 dark:text-amber-400 font-medium text-sm animate-pulse">
                  Connecting...
                </p>
              </div>
            )}

            {isActive && (
              <div className="flex flex-col items-center gap-4">
                <VoiceOrb state={orbState} amplitude={micAmplitude} />
                <p className="text-sm text-gray-400 dark:text-gray-500">
                  {isSpeaking ? "Speaking..." : "Listening..."}
                </p>
              </div>
            )}

            {status === "ended" && (
              <div className="flex flex-col items-center gap-4">
                <VoiceOrb state="idle" />
                <p className="text-gray-500 text-sm">Session ended</p>
                <button
                  onClick={() => {
                    sessionStartedRef.current = false;
                    startSession();
                  }}
                  className="text-blue-600 hover:text-blue-700 text-sm font-medium"
                >
                  Restart
                </button>
              </div>
            )}

            {error && (
              <p className="mt-4 text-red-600 text-sm text-center max-w-sm">{error}</p>
            )}
          </div>
        )}

        {/* Contacts phase — form + compact orb */}
        {uiPhase === "contacts" && (
          <div>
            {/* Compact voice orb — AI stays active during contacts entry */}
            {isActive && (
              <div className="flex items-center justify-center gap-3 mb-6 py-3 bg-gray-50 dark:bg-gray-900/50 rounded-xl">
                <VoiceOrb state={orbState} amplitude={micAmplitude} size="sm" />
                <div className="text-sm text-gray-500 dark:text-gray-400">
                  {isSpeaking ? "Speaking..." : "Listening — say a name to add by voice"}
                </div>
              </div>
            )}

            <PhaseContacts onComplete={handleContactsComplete} />
          </div>
        )}

        {/* Confirm phase */}
        {uiPhase === "confirm" && (
          <PhaseConfirm
            ownerName={data.name}
            language={data.language}
            contactCount={data.contacts.length}
            deliveryInstructions={data.deliveryInstructions}
            callPreferences={data.callPreferences}
            onConfirm={handleConfirm}
          />
        )}
      </div>
    </main>
  );
}

"use client";

import { useVoiceSession } from "@/hooks/useVoiceSession";
import { useCallback, useEffect, useRef, useState } from "react";
import VoiceOrb from "@/components/VoiceOrb";

interface Props {
  onComplete: (data: { name: string; language: string }) => void;
}

export default function PhaseBasics({ onComplete }: Props) {
  const pendingRef = useRef<{ name: string; language: string } | null>(null);
  const [waitingToTransition, setWaitingToTransition] = useState(false);

  const handlePhaseComplete = useCallback(
    (phase: number, data?: Record<string, unknown>) => {
      if (phase === 1 && data) {
        pendingRef.current = {
          name: (data.name as string) || "",
          language: (data.language as string) || "english",
        };
        setWaitingToTransition(true);
      }
    },
    []
  );

  const { status, error, isSpeaking, micAmplitude, startSession, endSession } =
    useVoiceSession({
      mode: "onboarding",
      onboardingPhase: 1,
      onPhaseComplete: handlePhaseComplete,
    });

  // Wait for AI to finish speaking the next-step introduction, then transition
  useEffect(() => {
    if (!waitingToTransition || !pendingRef.current) return;
    if (isSpeaking) return;

    const timer = setTimeout(() => {
      if (pendingRef.current) {
        onComplete(pendingRef.current);
      }
    }, 800);
    return () => clearTimeout(timer);
  }, [waitingToTransition, isSpeaking, onComplete]);

  const isActive = status === "connected";

  const orbState = !isActive
    ? status === "connecting"
      ? "connecting"
      : "idle"
    : isSpeaking
      ? "speaking"
      : "listening";

  return (
    <div className="flex flex-col items-center min-h-[60vh] justify-center">
      {status === "idle" && (
        <div className="flex flex-col items-center gap-6">
          <VoiceOrb state="idle" />
          <div className="text-center">
            <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
              Let&apos;s get started
            </h2>
            <p className="text-gray-500 dark:text-gray-400 text-sm max-w-xs">
              Tap start and tell the AI your name and preferred language.
            </p>
          </div>
          <button
            onClick={startSession}
            className="mt-2 bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-10 rounded-full text-base transition-all hover:shadow-lg active:scale-95"
          >
            Start
          </button>
        </div>
      )}

      {status === "connecting" && (
        <div className="flex flex-col items-center gap-6">
          <VoiceOrb state="connecting" />
          <p className="text-amber-600 dark:text-amber-400 font-medium text-sm">
            Connecting...
          </p>
        </div>
      )}

      {isActive && (
        <div className="flex flex-col items-center gap-4">
          <VoiceOrb state={orbState} amplitude={micAmplitude} />
          <p className="text-sm text-gray-400 dark:text-gray-500">
            {isSpeaking ? "Speaking..." : "Listening..."}
          </p>
          <button
            onClick={endSession}
            className="mt-4 bg-red-500/10 hover:bg-red-500/20 text-red-600 dark:text-red-400 font-medium py-2 px-6 rounded-full text-sm transition-colors"
          >
            End
          </button>
        </div>
      )}

      {status === "ended" && (
        <div className="flex flex-col items-center gap-4">
          <VoiceOrb state="idle" />
          <p className="text-gray-500 text-sm">Session ended</p>
        </div>
      )}

      {error && (
        <p className="mt-4 text-red-600 text-sm text-center">{error}</p>
      )}
    </div>
  );
}

