"use client";

interface VoiceOrbProps {
  state: "idle" | "connecting" | "listening" | "speaking";
  amplitude?: number; // 0-1, mic amplitude when listening
  size?: "sm" | "md" | "lg";
}

export default function VoiceOrb({ state, amplitude = 0, size = "lg" }: VoiceOrbProps) {
  const sizeMap = { sm: 80, md: 120, lg: 160 };
  const px = sizeMap[size];

  // Dynamic scale when listening based on mic amplitude
  const listenScale = state === "listening" ? 1 + amplitude * 0.25 : 1;
  const speakScale = state === "speaking" ? undefined : undefined; // handled by CSS animation

  return (
    <div
      className="relative flex items-center justify-center"
      style={{ width: px * 1.8, height: px * 1.8 }}
    >
      {/* Expanding rings when speaking */}
      {state === "speaking" && (
        <>
          <div
            className="absolute rounded-full bg-blue-400/10 animate-[orb-ring_2s_ease-out_infinite]"
            style={{ width: px * 1.6, height: px * 1.6 }}
          />
          <div
            className="absolute rounded-full bg-blue-400/15 animate-[orb-ring_2s_ease-out_infinite_0.6s]"
            style={{ width: px * 1.3, height: px * 1.3 }}
          />
        </>
      )}

      {/* Amplitude ring when listening — grows/shrinks with voice */}
      {state === "listening" && amplitude > 0.05 && (
        <div
          className="absolute rounded-full bg-emerald-400/20 transition-transform duration-100"
          style={{
            width: px * 1.2,
            height: px * 1.2,
            transform: `scale(${1 + amplitude * 0.4})`,
          }}
        />
      )}

      {/* Glow */}
      <div
        className={`absolute rounded-full blur-2xl transition-all duration-300 ${
          state === "speaking"
            ? "bg-blue-500/30 opacity-100"
            : state === "listening"
              ? "bg-emerald-500/20 opacity-100"
              : state === "connecting"
                ? "bg-amber-500/20 opacity-100"
                : "bg-gray-500/10 opacity-40"
        }`}
        style={{ width: px * 1.1, height: px * 1.1 }}
      />

      {/* Main orb */}
      <div
        className={`relative z-10 rounded-full flex items-center justify-center shadow-2xl ${
          state === "speaking"
            ? "bg-gradient-to-br from-blue-400 via-indigo-500 to-purple-600 animate-[orb-speak_1s_ease-in-out_infinite]"
            : state === "listening"
              ? "bg-gradient-to-br from-emerald-400 via-teal-500 to-cyan-600"
              : state === "connecting"
                ? "bg-gradient-to-br from-amber-400 via-orange-500 to-red-400 animate-pulse"
                : "bg-gradient-to-br from-gray-400 via-gray-500 to-gray-600"
        }`}
        style={{
          width: px,
          height: px,
          transform: state === "listening" ? `scale(${listenScale})` : undefined,
          transition: state === "listening" ? "transform 100ms ease-out" : undefined,
        }}
      >
        {/* Inner highlight */}
        <div
          className="absolute rounded-full bg-white/10"
          style={{
            width: px * 0.6,
            height: px * 0.6,
            top: px * 0.1,
            left: px * 0.15,
          }}
        />

        {/* Icon */}
        <svg
          className="relative z-10 text-white/90"
          style={{ width: px * 0.28, height: px * 0.28 }}
          fill="currentColor"
          viewBox="0 0 24 24"
        >
          {state === "speaking" ? (
            <path d="M3 9v6h4l5 5V4L7 9H3zm13.5 3c0-1.77-1.02-3.29-2.5-4.03v8.05c1.48-.73 2.5-2.25 2.5-4.02zM14 3.23v2.06c2.89.86 5 3.54 5 6.71s-2.11 5.85-5 6.71v2.06c4.01-.91 7-4.49 7-8.77s-2.99-7.86-7-8.77z" />
          ) : (
            <path d="M12 14c1.66 0 3-1.34 3-3V5c0-1.66-1.34-3-3-3S9 3.34 9 5v6c0 1.66 1.34 3 3 3zm5-3c0 2.76-2.24 5-5 5s-5-2.24-5-5H5c0 3.53 2.61 6.43 6 6.92V21h2v-3.08c3.39-.49 6-3.39 6-6.92h-2z" />
          )}
        </svg>
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { useVoiceSession } from "@/hooks/useVoiceSession";
import VoiceOrb from "@/components/VoiceOrb";

export default function CallInterface() {
  const [phoneNumber, setPhoneNumber] = useState("");

  const { status, error, callerInfo, isSpeaking, micAmplitude, startSession, endSession } =
    useVoiceSession({
      phoneNumber,
      mode: "call",
    });

  const isInCall = status === "connected" || status === "bypass";

  const handleStartCall = () => {
    if (!phoneNumber.trim()) return;
    startSession();
  };

  const orbState = !isInCall
    ? status === "connecting" ? "connecting" : "idle"
    : isSpeaking ? "speaking" : "listening";

  if (isInCall || status === "connecting") {
    return (
      <div className="flex flex-col items-center justify-center min-h-[80vh] px-4">
        <VoiceOrb state={orbState} amplitude={micAmplitude} />

        <p className="mt-6 text-sm text-gray-400 dark:text-gray-500">
          {status === "connecting"
            ? "Connecting..."
            : isSpeaking
              ? "Speaking..."
              : "Listening..."}
        </p>

        {callerInfo && (
          <div className="mt-4 flex items-center gap-2 text-xs">
            <span className={`px-2 py-1 rounded-full font-medium ${
              callerInfo.priority === "high"
                ? "bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400"
                : callerInfo.priority === "medium"
                  ? "bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400"
                  : "bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400"
            }`}>
              {callerInfo.caller_type}
            </span>
            {callerInfo.caller_name && (
              <span className="text-gray-500">{callerInfo.caller_name}</span>
            )}
            {callerInfo.is_scammer && (
              <span className="px-2 py-1 rounded-full bg-red-600 text-white font-bold">
                SCAMMER
              </span>
            )}
          </div>
        )}

        <p className="mt-4 text-xs text-gray-400 font-mono">{phoneNumber}</p>

        <button
          onClick={endSession}
          className="mt-6 w-14 h-14 bg-red-600 hover:bg-red-700 rounded-full flex items-center justify-center transition-colors active:scale-95 shadow-lg"
        >
          <svg className="w-6 h-6 text-white" fill="currentColor" viewBox="0 0 24 24">
            <path d="M12 9c-1.6 0-3.15.25-4.6.72v3.1c0 .39-.23.74-.56.9-.98.49-1.87 1.12-2.66 1.85-.18.18-.43.28-.7.28-.28 0-.53-.11-.71-.29L.29 13.08a.956.956 0 01-.29-.7c0-.28.11-.53.29-.71C3.34 8.78 7.46 7 12 7s8.66 1.78 11.71 4.67c.18.18.29.43.29.71 0 .28-.11.53-.29.71l-2.48 2.48c-.18.18-.43.29-.71.29-.27 0-.52-.11-.7-.28a11.27 11.27 0 00-2.67-1.85.996.996 0 01-.56-.9v-3.1C15.15 9.25 13.6 9 12 9z" />
          </svg>
        </button>

        {error && <p className="mt-4 text-red-600 text-sm">{error}</p>}
      </div>
    );
  }

  return (
    <div className="flex flex-col items-center justify-center min-h-[80vh] px-4">
      <VoiceOrb state="idle" size="md" />

      <h1 className="mt-8 text-xl font-semibold text-gray-900 dark:text-white">
        Simulate a Call
      </h1>
      <p className="mt-2 text-sm text-gray-500 dark:text-gray-400 text-center max-w-xs">
        Enter a phone number to simulate an incoming call.
      </p>

      <div className="mt-8 w-full max-w-xs">
        <input
          type="tel"
          value={phoneNumber}
          onChange={(e) => setPhoneNumber(e.target.value)}
          placeholder="Phone number"
          className="w-full px-4 py-3 text-center text-lg border border-gray-200 dark:border-gray-700 rounded-xl focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white dark:bg-gray-900 font-mono"
        />
      </div>

      <button
        onClick={handleStartCall}
        disabled={!phoneNumber.trim()}
        className="mt-6 bg-green-600 hover:bg-green-700 disabled:bg-gray-300 dark:disabled:bg-gray-700 text-white font-medium py-3 px-10 rounded-full text-base transition-all hover:shadow-lg active:scale-95 disabled:cursor-not-allowed"
      >
        Start Call
      </button>

      {status === "blocked" && (
        <p className="mt-4 text-red-600 text-sm">{error || "This number has been blocked."}</p>
      )}
      {status === "ended" && (
        <p className="mt-4 text-gray-500 text-sm">Call ended</p>
      )}
      {error && status === "error" && (
        <p className="mt-4 text-red-600 text-sm">{error}</p>
      )}
    </div>
  );
}

