"use client";

import { useState, useCallback, useEffect, useRef } from "react";
import { useRouter } from "next/navigation";
import PhaseStepper from "@/components/onboarding/PhaseStepper";
import PhaseContacts from "@/components/onboarding/PhaseContacts";
import PhaseConfirm from "@/components/onboarding/PhaseConfirm";
import VoiceOrb from "@/components/VoiceOrb";
import { useVoiceSession } from "@/hooks/useVoiceSession";

type UIPhase = "voice" | "contacts" | "confirm";

interface OnboardingData {
  name: string;
  language: string;
  contacts: { name: string; relationship: string; phone_number: string; priority: string }[];
  deliveryInstructions: string;
  callPreferences: Record<string, string>;
  customRules: string[];
}

export default function OnboardingPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(true);
  const [uiPhase, setUIPhase] = useState<UIPhase>("voice");
  const [step, setStep] = useState(1);
  const [data, setData] = useState<OnboardingData>({
    name: "",
    language: "english",
    contacts: [],
    deliveryInstructions: "",
    callPreferences: {},
    customRules: [],
  });
  const sessionStartedRef = useRef(false);

  useEffect(() => {
    fetch("/api/status")
      .then((r) => r.json())
      .then((d) => {
        if (d.onboarding_complete) router.replace("/dashboard");
        else setLoading(false);
      })
      .catch(() => setLoading(false));
  }, [router]);

  const handlePhaseComplete = useCallback(
    (phase: string | number, phaseData?: Record<string, unknown>) => {
      switch (phase) {
        case "basics_saved":
          if (phaseData) {
            setData((prev) => ({
              ...prev,
              name: (phaseData.name as string) || prev.name,
              language: (phaseData.language as string) || prev.language,
            }));
          }
          setStep(2);
          break;

        case "show_contacts":
          setUIPhase("contacts");
          setStep(2);
          break;

        case "contact_added":
          if (phaseData) {
            setData((prev) => ({
              ...prev,
              contacts: [
                ...prev.contacts,
                {
                  name: (phaseData.name as string) || "",
                  phone_number: (phaseData.phone_number as string) || "",
                  relationship: (phaseData.relationship as string) || "",
                  priority: (phaseData.priority as string) || "medium",
                },
              ],
            }));
          }
          break;

        case "contacts_done":
          setUIPhase("voice");
          setStep(3);
          break;

        case "preferences_saved":
          if (phaseData) {
            setData((prev) => ({
              ...prev,
              deliveryInstructions: (phaseData.delivery_instructions as string) || "",
              callPreferences: (phaseData.call_preferences as Record<string, string>) || {},
              customRules: (phaseData.custom_rules as string[]) || [],
            }));
          }
          setUIPhase("confirm");
          setStep(4);
          break;
      }
    },
    []
  );

  const { status, error, isSpeaking, micAmplitude, startSession, endSession } =
    useVoiceSession({
      mode: "onboarding",
      onboardingPhase: 0,
      onPhaseComplete: handlePhaseComplete,
    });

  // Auto-start the voice session once loaded
  useEffect(() => {
    if (!loading && !sessionStartedRef.current && status === "idle") {
      sessionStartedRef.current = true;
      startSession();
    }
  }, [loading, status, startSession]);

  const handleContactsComplete = useCallback(
    async (
      contacts: { name: string; relationship: string; phone_number: string; priority: string }[]
    ) => {
      for (const contact of contacts) {
        await fetch("/api/contacts", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(contact),
        });
      }
      setData((prev) => ({
        ...prev,
        contacts: [...prev.contacts, ...contacts],
      }));
      setUIPhase("voice");
      setStep(3);
    },
    []
  );

  const handleConfirm = useCallback(async () => {
    await fetch("/api/onboarding", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        name: data.name,
        default_language: data.language,
        delivery_instructions: data.deliveryInstructions,
        call_preferences: data.callPreferences,
        custom_rules: data.customRules,
      }),
    });
    router.push("/dashboard");
  }, [data, router]);

  if (loading) {
    return (
      <main className="min-h-screen flex items-center justify-center bg-white dark:bg-gray-950">
        <div className="text-gray-500">Loading...</div>
      </main>
    );
  }

  const isActive = status === "connected";
  const orbState =
    !isActive
      ? status === "connecting"
        ? "connecting"
        : "idle"
      : isSpeaking
        ? "speaking"
        : "listening";

  return (
    <main className="min-h-screen bg-white dark:bg-gray-950 text-gray-900 dark:text-gray-100">
      <div className="max-w-2xl mx-auto py-8 px-4">
        <PhaseStepper current={step} />

        {/* Voice phase — full-screen orb */}
        {uiPhase === "voice" && (
          <div className="flex flex-col items-center justify-center min-h-[65vh]">
            {status === "idle" && !sessionStartedRef.current && (
              <div className="flex flex-col items-center gap-6">
                <VoiceOrb state="idle" />
                <div className="text-center">
                  <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-2">
                    Let&apos;s set up your AI Receptionist
                  </h2>
                  <p className="text-gray-500 dark:text-gray-400 text-sm max-w-xs">
                    We&apos;ll have a quick conversation to get everything configured.
                  </p>
                </div>
                <button
                  onClick={startSession}
                  className="mt-2 bg-blue-600 hover:bg-blue-700 text-white font-medium py-3 px-10 rounded-full text-base transition-all hover:shadow-lg active:scale-95"
                >
                  Start
                </button>
              </div>
            )}

            {status === "connecting" && (
              <div className="flex flex-col items-center gap-6">
                <VoiceOrb state="connecting" />
                <p className="text-amber-600 dark:text-amber-400 font-medium text-sm animate-pulse">
                  Connecting...
                </p>
              </div>
            )}

            {isActive && (
              <div className="flex flex-col items-center gap-4">
                <VoiceOrb state={orbState} amplitude={micAmplitude} />
                <p className="text-sm text-gray-400 dark:text-gray-500">
                  {isSpeaking ? "Speaking..." : "Listening..."}
                </p>
              </div>
            )}

            {status === "ended" && (
              <div className="flex flex-col items-center gap-4">
                <VoiceOrb state="idle" />
                <p className="text-gray-500 text-sm">Session ended</p>
                <button
                  onClick={() => {
                    sessionStartedRef.current = false;
                    startSession();
                  }}
                  className="text-blue-600 hover:text-blue-700 text-sm font-medium"
                >
                  Restart
                </button>
              </div>
            )}

            {error && (
              <p className="mt-4 text-red-600 text-sm text-center max-w-sm">{error}</p>
            )}
          </div>
        )}

        {/* Contacts phase — form + compact orb */}
        {uiPhase === "contacts" && (
          <div>
            {/* Compact voice orb — AI stays active during contacts entry */}
            {isActive && (
              <div className="flex items-center justify-center gap-3 mb-6 py-3 bg-gray-50 dark:bg-gray-900/50 rounded-xl">
                <VoiceOrb state={orbState} amplitude={micAmplitude} size="sm" />
                <div className="text-sm text-gray-500 dark:text-gray-400">
                  {isSpeaking ? "Speaking..." : "Listening — say a name to add by voice"}
                </div>
              </div>
            )}

            <PhaseContacts onComplete={handleContactsComplete} />
          </div>
        )}

        {/* Confirm phase */}
        {uiPhase === "confirm" && (
          <PhaseConfirm
            ownerName={data.name}
            language={data.language}
            contactCount={data.contacts.length}
            deliveryInstructions={data.deliveryInstructions}
            callPreferences={data.callPreferences}
            onConfirm={handleConfirm}
          />
        )}
      </div>
    </main>
  );
}

"use client";

interface Props {
  ownerName: string;
  language: string;
  contactCount: number;
  deliveryInstructions: string;
  callPreferences: Record<string, string>;
  onConfirm: () => void;
}

export default function PhaseConfirm({
  ownerName,
  language,
  contactCount,
  deliveryInstructions,
  callPreferences,
  onConfirm,
}: Props) {
  return (
    <div className="max-w-md mx-auto">
      <div className="text-center mb-8">
        <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-green-100 dark:bg-green-900/30 flex items-center justify-center">
          <svg className="w-8 h-8 text-green-600 dark:text-green-400" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M5 13l4 4L19 7" />
          </svg>
        </div>
        <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-1">
          All set!
        </h2>
        <p className="text-gray-500 dark:text-gray-400 text-sm">
          Review your setup and confirm to start your AI receptionist.
        </p>
      </div>

      <div className="space-y-3 mb-8">
        <SummaryRow label="Name" value={ownerName || "Not set"} />
        <SummaryRow label="Greeting language" value={language || "english"} />
        <SummaryRow
          label="Saved contacts"
          value={`${contactCount} contact${contactCount !== 1 ? "s" : ""}`}
        />
        <SummaryRow
          label="Delivery instructions"
          value={deliveryInstructions || "No specific instructions"}
        />
        {Object.keys(callPreferences).length > 0 && (
          <div className="bg-white dark:bg-gray-900 rounded-xl border border-gray-100 dark:border-gray-800 p-4">
            <div className="text-xs text-gray-400 uppercase tracking-wide mb-2">
              Call preferences
            </div>
            {Object.entries(callPreferences).map(([type, pref]) => (
              <div key={type} className="text-sm flex justify-between">
                <span className="capitalize text-gray-600 dark:text-gray-300">{type}</span>
                <span className={pref === "decline" ? "text-red-500" : "text-green-500"}>
                  {pref}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="text-center">
        <button
          onClick={onConfirm}
          className="bg-green-600 hover:bg-green-700 text-white font-medium py-3 px-10 rounded-full text-base transition-all hover:shadow-lg active:scale-95"
        >
          Confirm &amp; Start
        </button>
      </div>
    </div>
  );
}

function SummaryRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="bg-white dark:bg-gray-900 rounded-xl border border-gray-100 dark:border-gray-800 p-4 flex justify-between items-center">
      <span className="text-xs text-gray-400 uppercase tracking-wide">{label}</span>
      <span className="text-sm font-medium text-gray-900 dark:text-white capitalize">{value}</span>
    </div>
  );
}

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import CallLogList from "@/components/dashboard/CallLogList";

export default function DashboardPage() {
  const [ownerName, setOwnerName] = useState<string | null>(null);
  const [contactCount, setContactCount] = useState(0);

  useEffect(() => {
    fetch("/api/status")
      .then((r) => r.json())
      .then((data) => {
        setOwnerName(data.owner_name);
        setContactCount(data.contact_count ?? 0);
      })
      .catch(() => {});
  }, []);

  return (
    <main className="min-h-screen bg-gray-50 dark:bg-[#0a0a0f] text-gray-900 dark:text-gray-100">
      {/* Header */}
      <header className="sticky top-0 z-10 bg-white/80 dark:bg-[#0a0a0f]/80 backdrop-blur-xl border-b border-gray-200/60 dark:border-white/5">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-500 to-indigo-600 flex items-center justify-center shadow-lg shadow-blue-500/20">
              <svg className="w-5 h-5 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" />
              </svg>
            </div>
            <div>
              <h1 className="text-lg font-bold tracking-tight">
                {ownerName ? `${ownerName}'s Receptionist` : "AI Receptionist"}
              </h1>
              <p className="text-xs text-gray-500 dark:text-gray-500">
                Real-time call monitoring
              </p>
            </div>
          </div>
          <div className="flex items-center gap-2">
            <Link
              href="/call"
              className="flex items-center gap-2 bg-gradient-to-r from-green-500 to-emerald-600 hover:from-green-600 hover:to-emerald-700 text-white font-medium px-4 py-2 rounded-xl text-sm transition-all shadow-lg shadow-green-500/20 hover:shadow-green-500/30 active:scale-95"
            >
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M3 5a2 2 0 012-2h3.28a1 1 0 01.948.684l1.498 4.493a1 1 0 01-.502 1.21l-2.257 1.13a11.042 11.042 0 005.516 5.516l1.13-2.257a1 1 0 011.21-.502l4.493 1.498a1 1 0 01.684.949V19a2 2 0 01-2 2h-1C9.716 21 3 14.284 3 6V5z" />
              </svg>
              Simulate Call
            </Link>
          </div>
        </div>
      </header>

      {/* Stats bar */}
      <div className="max-w-5xl mx-auto px-4 sm:px-6 py-4">
        <div className="grid grid-cols-3 gap-3">
          <StatCard
            label="Saved Contacts"
            value={String(contactCount)}
            icon={
              <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M17 20h5v-2a3 3 0 00-5.356-1.857M17 20H7m10 0v-2c0-.656-.126-1.283-.356-1.857M7 20H2v-2a3 3 0 015.356-1.857M7 20v-2c0-.656.126-1.283.356-1.857m0 0a5.002 5.002 0 019.288 0M15 7a3 3 0 11-6 0 3 3 0 016 0z" />
