19	interface VoiceSessionOptions {
20	  phoneNumber?: string;
21	  mode?: "call" | "onboarding";
22	  onboardingPhase?: number;
23	  onPhaseComplete?: (phase: string | number, data?: Record<string, unknown>) => void;
24	}
