26	type SessionStatus =
27	  | "idle"
28	  | "connecting"
29	  | "connected"
30	  | "blocked"
31	  | "bypass"
32	  | "ended"
33	  | "error";
34	
35	export function useVoiceSession(options: VoiceSessionOptions = {}) {
36	  const {
37	    phoneNumber = "",
38	    mode = "call",
39	    onboardingPhase = 0,
40	    onPhaseComplete,
41	  } = options;
42	
43	  const [status, setStatus] = useState<SessionStatus>("idle");
44	  const [error, setError] = useState<string | null>(null);
45	  const [transcript, setTranscript] = useState<TranscriptEntry[]>([]);
46	  const [callerInfo, setCallerInfo] = useState<CallerInfo | null>(null);
47	  const [isSpeaking, setIsSpeaking] = useState(false);
48	  const [micAmplitude, setMicAmplitude] = useState(0);
49	
50	  const wsRef = useRef<WebSocket | null>(null);
51	  const audioContextRef = useRef<AudioContext | null>(null);
52	  const workletNodeRef = useRef<AudioWorkletNode | null>(null);
53	  const streamRef = useRef<MediaStream | null>(null);
54	  const playbackTimeRef = useRef<number>(0);
55	  const scheduledSourcesRef = useRef<AudioBufferSourceNode[]>([]);
56	  const isActiveRef = useRef(false);
57	
58	  const cancelQueuedAudio = useCallback(() => {
59	    for (const src of scheduledSourcesRef.current) {
60	      try { src.stop(); } catch { /* already stopped */ }
61	    }
62	    scheduledSourcesRef.current = [];
63	    playbackTimeRef.current = 0;
64	    setIsSpeaking(false);
65	  }, []);
66	
67	  const cleanup = useCallback(() => {
68	    isActiveRef.current = false;
69	    cancelQueuedAudio();
70	
71	    if (workletNodeRef.current) {
72	      workletNodeRef.current.disconnect();
73	      workletNodeRef.current = null;
74	    }
75	    if (streamRef.current) {
76	      streamRef.current.getTracks().forEach((t) => t.stop());
77	      streamRef.current = null;
78	    }
79	    if (audioContextRef.current) {
80	      audioContextRef.current.close().catch(() => {});
81	      audioContextRef.current = null;
82	    }
83	    if (wsRef.current) {
84	      wsRef.current.close();
85	      wsRef.current = null;
86	    }
87	  }, [cancelQueuedAudio]);
88	
89	  useEffect(() => {
90	    return () => cleanup();
91	  }, [cleanup]);
92	
93	  const startSession = useCallback(async () => {
94	    cleanup();
95	    setStatus("connecting");
96	    setError(null);
97	    setTranscript([]);
98	    setCallerInfo(null);
99	    setIsSpeaking(false);
100	    setMicAmplitude(0);
101	    isActiveRef.current = true;
102	
103	    try {
104	      const stream = await navigator.mediaDevices.getUserMedia({
105	        audio: {
106	          sampleRate: 24000,
107	          channelCount: 1,
108	          echoCancellation: true,
109	          noiseSuppression: true,
110	        },
111	      });
112	      streamRef.current = stream;
113	
114	      const audioContext = new AudioContext({ sampleRate: 24000 });
115	      audioContextRef.current = audioContext;
116	
117	      await audioContext.audioWorklet.addModule("/audio-processor.js");
118	      const source = audioContext.createMediaStreamSource(stream);
119	      const workletNode = new AudioWorkletNode(
120	        audioContext,
121	        "audio-capture-processor"
122	      );
123	      workletNodeRef.current = workletNode;
124	
125	      const wsUrl = `${getWsBaseUrl()}/ws/voice`;
126	      const ws = new WebSocket(wsUrl);
127	      wsRef.current = ws;
128	
129	      ws.onopen = () => {
130	        ws.send(
131	          JSON.stringify({
132	            type: mode === "onboarding" ? "start_onboarding" : "start_call",
133	            phone_number: phoneNumber,
134	            phase: onboardingPhase,
135	          })
136	        );
137	      };
138	
139	      workletNode.port.onmessage = (event) => {
140	        const { data, amplitude } = event.data;
141	
142	        if (amplitude !== undefined) {
143	          setMicAmplitude(Math.min(1, amplitude * 4));
144	        }
145	
146	        if (
147	          !isActiveRef.current ||
148	          !ws ||
149	          ws.readyState !== WebSocket.OPEN
150	        )
151	          return;
152	
153	        const bytes = new Uint8Array(data);
154	        let binary = "";
155	        for (let i = 0; i < bytes.byteLength; i++) {
156	          binary += String.fromCharCode(bytes[i]);
157	        }
158	        const base64 = btoa(binary);
159	        ws.send(JSON.stringify({ type: "audio_data", audio: base64 }));
160	      };
161	
162	      source.connect(workletNode);
163	      workletNode.connect(audioContext.destination);
164	
165	      ws.onmessage = (event) => {
166	        const msg = JSON.parse(event.data);
167	
168	        switch (msg.type) {
169	          case "status":
170	            if (msg.status === "connected") {
171	              setStatus("connected");
172	            } else if (msg.status === "bypass") {
173	              setStatus("bypass");
174	            }
175	            break;
176	
177	          case "blocked":
178	            setStatus("blocked");
179	            setError(msg.reason || "This number has been blocked.");
180	            cleanup();
181	            break;
182	
183	          case "audio_data":
184	            setIsSpeaking(true);
185	            playAudioQueued(msg.audio, audioContext, playbackTimeRef, scheduledSourcesRef);
186	            break;
187	
188	          case "audio_done":
189	            setIsSpeaking(false);
190	            break;
191	
192	          case "speech_started":
193	            cancelQueuedAudio();
194	            break;
195	
196	          case "transcript":
197	            setTranscript((prev) => [
198	              ...prev,
199	              { role: msg.role, text: msg.text },
200	            ]);
201	            break;
202	
203	          case "caller_info":
204	            setCallerInfo(msg);
205	            break;
206	
207	          case "onboarding_phase_complete":
208	            onPhaseComplete?.(msg.phase, msg.data);
209	            break;
210	
211	          case "error":
212	            setError(msg.message);
213	            setStatus("error");
214	            break;
215	        }
216	      };
217	
218	      ws.onclose = () => {
219	        if (isActiveRef.current) {
220	          setStatus("ended");
221	        }
222	      };
223	
224	      ws.onerror = () => {
225	        setError("WebSocket connection failed");
226	        setStatus("error");
227	      };
228	    } catch (err) {
229	      const message =
230	        err instanceof Error ? err.message : "Failed to start voice session";
231	      setError(message);
232	      setStatus("error");
233	      cleanup();
234	    }
235	  }, [phoneNumber, mode, onboardingPhase, onPhaseComplete, cleanup, cancelQueuedAudio]);
236	
237	  const endSession = useCallback(() => {
238	    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
239	      wsRef.current.send(JSON.stringify({ type: "end_call" }));
240	    }
241	    setStatus("ended");
242	    cleanup();
243	  }, [cleanup]);
244	
245	  return {
246	    status,
247	    error,
248	    transcript,
249	    callerInfo,
250	    isSpeaking,
251	    micAmplitude,
252	    startSession,
253	    endSession,
254	  };
255	}
