257	function playAudioQueued(
258	  base64Audio: string,
259	  audioContext: AudioContext,
260	  playbackTimeRef: React.MutableRefObject<number>,
261	  scheduledSourcesRef: React.MutableRefObject<AudioBufferSourceNode[]>
262	) {
263	  const binary = atob(base64Audio);
264	  const bytes = new Uint8Array(binary.length);
265	  for (let i = 0; i < binary.length; i++) {
266	    bytes[i] = binary.charCodeAt(i);
267	  }
268	
269	  const int16 = new Int16Array(bytes.buffer);
270	  const float32 = new Float32Array(int16.length);
271	  for (let i = 0; i < int16.length; i++) {
272	    float32[i] = int16[i] / 32768;
273	  }
274	
275	  const audioBuffer = audioContext.createBuffer(1, float32.length, 24000);
276	  audioBuffer.getChannelData(0).set(float32);
277	
278	  const source = audioContext.createBufferSource();
279	  source.buffer = audioBuffer;
280	  source.connect(audioContext.destination);
281	
282	  const startTime = Math.max(audioContext.currentTime + 0.01, playbackTimeRef.current);
283	  source.start(startTime);
284	  playbackTimeRef.current = startTime + audioBuffer.duration;
285	
286	  scheduledSourcesRef.current.push(source);
287	  source.onended = () => {
288	    scheduledSourcesRef.current = scheduledSourcesRef.current.filter((s) => s !== source);
289	  };
290	}
