268	function ActionBtn({
269	  label,
270	  onClick,
271	  icon,
272	  variant,
273	}: {
274	  label: string;
275	  onClick: () => void;
276	  icon: React.ReactNode;
277	  variant: "blue" | "red" | "gray";
278	}) {
279	  const colors = {
280	    blue: "bg-blue-50 hover:bg-blue-100 text-blue-700 dark:bg-blue-500/10 dark:hover:bg-blue-500/20 dark:text-blue-400",
281	    red: "bg-red-50 hover:bg-red-100 text-red-700 dark:bg-red-500/10 dark:hover:bg-red-500/20 dark:text-red-400",
282	    gray: "bg-gray-50 hover:bg-gray-100 text-gray-700 dark:bg-gray-500/10 dark:hover:bg-gray-500/20 dark:text-gray-400",
283	  };
284	
285	  return (
286	    <button
287	      onClick={(e) => {
288	        e.stopPropagation();
289	        onClick();
290	      }}
291	      className={`flex items-center gap-1.5 text-xs font-medium px-3 py-1.5 rounded-lg transition-colors ${colors[variant]}`}
292	    >
293	      {icon}
294	      {label}
295	    </button>
296	  );
297	}
