299	function getTimeAgo(timestamp: number): string {
300	  const seconds = Math.floor(Date.now() / 1000 - timestamp);
301	  if (seconds < 60) return "just now";
302	  if (seconds < 3600) return `${Math.floor(seconds / 60)}m ago`;
303	  if (seconds < 86400) return `${Math.floor(seconds / 3600)}h ago`;
304	  return new Date(timestamp * 1000).toLocaleDateString();
305	}
