234	                <VoiceOrb state={orbState} amplitude={micAmplitude} />
235	                <p className="text-sm text-gray-400 dark:text-gray-500">
236	                  {isSpeaking ? "AI is speaking..." : "Listening..."}
237	                </p>
238	              </div>
239	            )}
240	
241	            {status === "ended" && (
242	              <div className="flex flex-col items-center gap-4">
243	                <VoiceOrb state="idle" />
244	                <p className="text-gray-500 text-sm">Session ended</p>
245	                <button
246	                  onClick={() => {
247	                    sessionStartedRef.current = false;
248	                    startSession();
249	                  }}
250	                  className="text-blue-600 hover:text-blue-700 text-sm font-medium"
251	                >
252	                  Restart
253	                </button>
254	              </div>
255	            )}
256	
257	            {error && (
258	              <p className="mt-4 text-red-600 text-sm text-center max-w-sm">{error}</p>
259	            )}
260	          </div>
261	        )}
262	
263	        {/* Contacts phase — form + compact orb */}
264	        {uiPhase === "contacts" && (
265	          <div>
266	            {/* Compact voice orb — AI stays active during contacts entry */}
267	            {isActive && (
268	              <div className="flex items-center justify-center gap-3 mb-6 py-3 bg-gray-50 dark:bg-gray-900/50 rounded-xl">
269	                <VoiceOrb state={orbState} amplitude={micAmplitude} size="sm" />
270	                <div className="text-sm text-gray-500 dark:text-gray-400">
271	                  {isSpeaking ? "AI is speaking..." : "Listening — say a name to add by voice"}
272	                </div>
273	              </div>
274	            )}
275	
276	            <PhaseContacts
277	              onComplete={handleContactsComplete}
278	              onChange={(contacts) => { pendingFormContactsRef.current = contacts; }}
279	            />
280	          </div>
281	        )}
282	
283	        {/* Confirm phase */}
284	        {uiPhase === "confirm" && (
285	          <PhaseConfirm
286	            ownerName={data.name}
287	            language={data.language}
288	            contactCount={data.contacts.length}
289	            deliveryInstructions={data.deliveryInstructions}
290	            callPreferences={data.callPreferences}
291	            onConfirm={handleConfirm}
292	          />
293	        )}
294	      </div>
295	    </main>
296	  );
297	}
